window.BANQUE_INFINI = {"module":"annee-2/theorique/semestre-1/eaif-3","titre":"EAIF III","sources":[{"t":"Chaînes musculaires","q":"chaines-musculaires/quiz.html","f":"chaines-musculaires/fiche.html"},{"t":"PNF — Facilitation neuromusculaire proprioceptive","q":"pnf/quiz.html","f":"pnf/fiche.html"},{"t":"Rééducation posturale globale","q":"reeducation-posturale/quiz.html","f":"reeducation-posturale/fiche.html"},{"t":"Santé au travail","q":"sante-au-travail/quiz.html","f":"sante-au-travail/fiche.html"},{"t":"Stabilité du complexe articulaire de l'épaule","q":"stabilite-epaule/quiz.html","f":"stabilite-epaule/fiche.html"},{"t":"Stabilité du complexe lombo-pelvi-fémoral","q":"stabilite-lombaire/quiz.html","f":"stabilite-lombaire/fiche.html"}],"questions":[{"q":"Qui parle pour la première fois de chaîne musculaire ?","o":["Madame Mézières","Philippe Souchard","Léopold Busquet","Tom Myers"],"r":0,"e":"Elle affirme que « toutes les déviations musculaires sont causées par la lordose » et parle du MOI comme être bio-psycho-social.","s":0},{"q":"Qui a créé la méthode de RPG ?","o":["Philippe Souchard","Madame Mézières","Godelieve Denys-Struyf","Tom Myers"],"r":0,"e":"Il utilise des étirements globaux impliquant tous les groupes musculaires du corps.","s":0},{"q":"Qui a créé les méridiens myofasciaux (trains anatomiques) ?","o":["Tom Myers","Léopold Busquet","Philippe Souchard","Madame Mézières"],"r":0,"e":"Par l'étude des voies fasciales.","s":0},{"q":"Quel est l'ordre hiérarchique des trois lois des chaînes musculaires ?","o":["Équilibre, économie, confort","Confort, équilibre, économie","Économie, confort, équilibre","Confort, économie, équilibre"],"r":0,"e":"Cette hiérarchie doit être respectée dans l'analyse de la statique.","s":0},{"q":"Quels systèmes assurent la loi de l'équilibre ?","o":["Le système nerveux sympathique et le système proprioceptif","Le système parasympathique et le système visuel, par les yeux","Le système vestibulaire seul, par l'oreille interne","Le système musculaire seul, par le tonus de posture"],"r":0,"e":"Le sympathique régule l'équilibre biologique, le proprioceptif l'équilibre de la verticalité.","s":0},{"q":"Quel muscle assure la loi de l'économie ?","o":["Le diaphragme","Le psoas","Le transverse de l'abdomen","Le carré des lombes"],"r":0,"e":"Il travaille constamment et de façon économique.","s":0},{"q":"Qu'est-ce qu'une contracture primaire ?","o":["Une nouvelle posture, pour éviter la souffrance, qui coûte de l'énergie","Une contracture musculaire aiguë, après un effort violent et inhabituel","Une rétraction tendineuse, après une immobilisation prolongée","Un spasme réflexe, en réponse à une douleur articulaire"],"r":0,"e":"Un ajustement à la contracture primaire détermine ensuite une contracture secondaire.","s":0},{"q":"Quel est le rôle du diaphragme dans les chaînes musculaires ?","o":["Il est le point de convergence et d'union de toutes les chaînes","Il n'intervient que dans la respiration, sans aucun rôle dans les chaînes","Il appartient uniquement à la chaîne de flexion antérieure","Il n'a aucun rôle postural, seulement un rôle viscéral"],"r":0,"e":"Il fonctionne de manière permanente et est essentiel dans sa relation avec toutes les fonctions corporelles.","s":0},{"q":"À quel niveau l'aorte traverse-t-elle le diaphragme ?","o":["T12","T9","T10","T8"],"r":0,"e":"Veine cave à T9, œsophage à T10, aorte à T12.","s":0},{"q":"À quel niveau la veine cave traverse-t-elle le diaphragme ?","o":["T9","T10","T12","T7"],"r":0,"e":"Son orifice est une pseudo-valve qui module la projection horizontale.","s":0},{"q":"À quel niveau l'œsophage traverse-t-il le diaphragme ?","o":["T10","T9","T12","L1"],"r":0,"e":"L'orifice œsophagien est à gauche, essentiellement musculaire, avec une fonction proprioceptive et quantitative.","s":0},{"q":"Pourquoi l'orifice de l'aorte est-il fibreux et non élastique ?","o":["Pour ne pas perturber le flux artériel","Pour permettre l'expansion de l'aorte","Pour amortir les chocs","Pour faciliter la torsion"],"r":0,"e":"L'aorte est aussi placée près de la ligne de gravité pour rester au centre lors des torsions.","s":0},{"q":"Quel effet a un diaphragme bloqué en inspiration sur la posture ?","o":["Une lordose cervicale accentuée, pour le confort cardiaque","Une cyphose thoracique accentuée, pour le confort pulmonaire","Une rectitude lombaire, pour le confort digestif","Aucun effet postural, le diaphragme restant indépendant"],"r":0,"e":"Bloqué en expiration, la stimulation du muscle cardiaque ne se fait pas, avec dépôt de graisse dans les coronaires.","s":0},{"q":"Qu'est-ce que la membrane de Laimer ?","o":["Un cordon graisseux qui protège l'orifice œsophagien de l'échauffement","Un ligament vertébral qui relie les corps de T12 et L1","Un fascia thoraco-lombaire qui gaine les muscles érecteurs du rachis","Une aponévrose diaphragmatique qui recouvre le centre phrénique"],"r":0,"e":"Elle protège la zone de la descente et de la montée du diaphragme.","s":0},{"q":"Quelle est l'origine du psoas majeur ?","o":["Corps et processus transverses de T12 à L5","Crête iliaque et ligament ilio-lombaire, en arrière","12ᵉ côte et processus transverses de L1 à L5","Sacrum et coccyx, à leur face antérieure"],"r":0,"e":"Le psoas mineur a une origine plus restreinte aux corps et disques de T12 et L1 ; les deux s'insèrent sur le petit trochanter.","s":0},{"q":"Quel muscle contrôle la rotation du psoas sur les vertèbres (point fixe lombaire) ?","o":["Le grand dorsal controlatéral","Le carré des lombes homolatéral","Le grand fessier","Le transverse de l'abdomen"],"r":0,"e":"Il agit via une contre-rotation.","s":0},{"q":"Que fait le psoas en point fixe fémoral ?","o":["Il lordose le rachis lombaire, l'incline de son côté, le tourne vers la convexité","Il cyphose le rachis lombaire, fléchit le tronc vers l'avant et l'incline du côté opposé","Il n'a aucune action sur la colonne en point fixe fémoral","Il fléchit le tronc en avant, sans inclinaison ni rotation"],"r":0,"e":"Cela survient quand on prend appui au sol avec besoin de verticalité et de rééquilibre.","s":0},{"q":"Quelle est l'action du carré des lombes ?","o":["Inclinaison latérale, fixation de la 12ᵉ côte, aide à l'expiration","Flexion du tronc, fixation de la 5ᵉ lombaire, aide à l'inspiration","Rotation de la hanche, fixation du fémur, aide à la marche","Extension cervicale, fixation de la tête, aide à la déglutition"],"r":0,"e":"Ses fibres droites appartiennent à une chaîne d'extension, ses fibres obliques au système croisé.","s":0},{"q":"Que protège la ligne blanche sous-ombilicale ?","o":["Les organes du petit bassin des variations de pression","Le diaphragme des tractions vers le bas, à l'inspiration","Le foie des chocs directs, sur le flanc droit","L'estomac des variations de volume, après les repas"],"r":0,"e":"Elle est très fermée et renforcée par les muscles droit et transverse de l'abdomen.","s":0},{"q":"Quels muscles favorisent la diastase sus-ombilicale ?","o":["Les rhomboïdes et le grand dentelé","Le droit de l'abdomen, en contraction","Le transverse de l'abdomen, en expiration","Le carré des lombes, en inclinaison"],"r":0,"e":"Quand la diastase épuise sa capacité physiologique d'écartement, le droit de l'abdomen entre en action.","s":0},{"q":"Par où passe la ligne de gravité au niveau du crâne ?","o":["Par le foramen magnum, avec 2/3 du poids de la tête en avant","Par le vertex, avec le poids de la tête réparti à moitié de chaque côté","Par l'os frontal, avec 1/3 du poids de la tête en avant","Par la protubérance occipitale, avec tout le poids en arrière"],"r":0,"e":"Au niveau plantaire elle passe en avant de la cheville : le résultat est un déséquilibre antérieur.","s":0},{"q":"Pourquoi le déséquilibre antérieur est-il physiologiquement utile ?","o":["C'est un premier pas contre l'inertie, en faveur de la marche","Il économise le tissu osseux, en déchargeant les vertèbres","Il protège les viscères abdominaux des chocs, en les plaquant en avant contre la paroi","Il diminue la lordose lombaire, en reculant le bassin"],"r":0,"e":"Dans un équilibre parfait, les centres d'équilibre seraient constamment en alerte, ce qui mènerait à l'épuisement.","s":0},{"q":"Pourquoi les muscles ne conviennent-ils pas à la fonction statique ?","o":["Un muscle sollicité sans arrêt se fibrose, s'atrophie et consomme beaucoup","Ils sont trop faibles pour porter le poids du corps pendant des heures","Ils manquent d'innervation pour tenir une contraction prolongée","Ils ne résistent pas à la gravité, même pendant quelques minutes debout"],"r":0,"e":"L'os, par sa structure alvéolaire et sa plasticité, et le tissu conjonctif sont mieux adaptés.","s":0},{"q":"Que fait le côlon transverse face aux forces descendantes du diaphragme ?","o":["Il oppose une contre-force vers le haut et écarte les côtes inférieures","Il se comprime sans réaction, en transmettant la pression au bassin","Il descend avec le diaphragme, en se plaquant contre la vessie","Il se vide de son contenu, en accélérant le transit vers le côlon descendant"],"r":0,"e":"C'est un élément clé de l'appui hydropneumatique abdominal.","s":0},{"q":"Quelle est la relation entre lordose lombaire et petit bassin ?","o":["La lordose protège les organes pelviens, et leur confort règle son degré","La lordose n'a aucun rapport avec le petit bassin ni avec ses organes","La lordose comprime les organes pelviens, quelle que soit la posture","Le petit bassin détermine seul la cyphose thoracique et la position de la tête"],"r":0,"e":"Les forces exercées par le diaphragme se reflètent à travers les ailes iliaques.","s":0},{"q":"Où commence et où se termine la chaîne posturale ?","o":["Des fosses nasales à l'extrémité des orteils","De l'occiput au sacrum, le long des épineuses","Du sternum aux genoux, par la face antérieure","Du crâne aux mains, par les membres supérieurs et la ceinture"],"r":0,"e":"Elle est la structure conjonctive la plus étendue du plan postérieur.","s":0},{"q":"Quelle vertèbre organise la flexion sans être incluse dans le mouvement ?","o":["L3","L5","T12","S1"],"r":0,"e":"Au-dessus de L3 le thorax s'incline vers l'avant, en dessous le bassin se postériorise.","s":0},{"q":"Quel est le point fixe commun du système musculaire reliant colonne cervicale, ceinture scapulaire et membre supérieur ?","o":["L'apophyse coracoïde","L'acromion","Le manubrium sternal","L'épine de la scapula"],"r":0,"e":"C'est ce qui permet au système droit d'être accompagné en haut du corps.","s":0},{"q":"Quel est le centre de convergence de la chaîne croisée antérieure ?","o":["Le nombril","L3","Le sternum","Le pubis"],"r":0,"e":"La chaîne croisée postérieure a L3 comme centre de convergence.","s":0},{"q":"Comment travaillent les chaînes croisées et les systèmes de flexion/extension ?","o":["De façon complémentaire et non antagoniste","De façon strictement antagoniste, l'une freinant l'autre","De façon indépendante, chacune pour son propre plan","En alternance stricte, jamais en même temps"],"r":0,"e":"Les chaînes croisées ont besoin des systèmes de flexion et d'extension pour assurer la stabilité et la statique.","s":0},{"q":"Madame Mézières décrit le MOI comme :","o":["Un être purement biomécanique","Un être bio-psycho-social","Une somme de segments","Un système nerveux"],"r":1,"e":"Elle est la première à parler de chaîne musculaire, avec la formule « toutes les déviations musculaires sont causées par la lordose ».","s":0},{"q":"Godelieve Denys-Struyf a développé :","o":["La méthode de rééducation posturale globale","Une méthode personnalisée de correction du geste","Les méridiens myofasciaux et les trains anatomiques","La méthode de facilitation neuromusculaire proprioceptive"],"r":1,"e":"Sa question directrice : comment utilisons-nous le corps dans les différents mouvements de la vie quotidienne ? La méthode réorganise aussi le geste.","s":0},{"q":"Léopold Busquet défend l'idée que :","o":["La lordose lombaire est la cause de toutes les douleurs","Un bon équilibre conditionne la posture et la liberté de mouvement","Les fascias forment des trains anatomiques continus du corps","L'étirement doit rester analytique, muscle par muscle, sans globalité"],"r":1,"e":"Tom Myers est l'auteur des méridiens myofasciaux, issus de l'étude des voies fasciales ; Souchard, celui de la RPG.","s":0},{"q":"Parmi les principes fondamentaux d'une chaîne musculaire, le cours cite :","o":["Aller de la tête aux pieds, intégrer tous les muscles, sans aucune faille","Se limiter à un seul membre, de la racine à l'extrémité","N'inclure que les muscles superficiels, visibles et palpables sous la peau","Fonctionner sans lien avec les autres chaînes du corps"],"r":0,"e":"Une chaîne doit en outre obéir aux trois lois hiérarchisées : équilibre, économie, confort.","s":0},{"q":"Dans la loi de l'équilibre, le système proprioceptif régule :","o":["L'équilibre biologique des fonctions","L'équilibre de la verticalité","La dépense énergétique","Le confort"],"r":1,"e":"Le système nerveux sympathique régule, lui, l'équilibre biologique de toutes les fonctions. Les deux se partagent la première loi.","s":0},{"q":"La loi du confort énonce que l'homme cherche à vivre dans le confort :","o":["Sans aucun coût énergétique, au repos comme en mouvement","Même au prix d'une dépense d'énergie supplémentaire","Uniquement au repos, en position allongée ou assise","Uniquement en cas de douleur, pour la soulager"],"r":1,"e":"C'est la troisième et dernière loi dans l'ordre hiérarchique : équilibre d'abord, économie ensuite, confort en dernier.","s":0},{"q":"La contracture secondaire résulte :","o":["D'un traumatisme direct sur le muscle, lors d'une chute","D'un ajustement à la contracture primaire, pour la posture","D'une carence musculaire en protéines, chez le sujet dénutri","D'un défaut de croissance de l'os, pendant l'adolescence"],"r":1,"e":"Il se produit alors une inversion dans la hiérarchie de fonctionnement : la priorité devient le confort et l'absence de douleur.","s":0},{"q":"Les schémas de compensation aboutissent selon le cours :","o":["À une amélioration de la mobilité et de la souplesse","À la douleur et à une déformation par des tensions fixées","À un renforcement musculaire global des chaînes concernées","À une meilleure économie d'énergie au quotidien"],"r":1,"e":"Le besoin de confort est alors satisfait au prix d'une dépense énergétique accrue, d'une fatigue supplémentaire et d'un travail diaphragmatique majoré.","s":0},{"q":"Le diaphragme est constitué de fibres musculaires :","o":["Longitudinales et parallèles, du sternum aux vertèbres","Semi-circulaires, convergeant vers le centre phrénique","Obliques et croisées, comme celles des intercostaux et des muscles abdominaux","Circulaires et concentriques, autour de l'orifice œsophagien"],"r":1,"e":"Il exerce, à travers le tissu conjonctif, une action jusqu'à la périphérie — ce qui fonde son statut de carrefour de toutes les chaînes.","s":0},{"q":"L'orifice de la veine cave au niveau T9 comporte :","o":["Une structure fibreuse rigide, qui garde un calibre fixe","Une pseudo-valve qui module sa projection horizontale","Un sphincter musculaire, qui ferme la veine à l'expiration","Aucune structure particulière, seulement un orifice dans le centre tendineux"],"r":1,"e":"La montée du sang veineux s'en trouve facilitée à l'inspiration et freinée à l'expiration : le diaphragme agit comme une pompe veineuse.","s":0},{"q":"L'orifice œsophagien, situé à T10, est :","o":["Fibreux et rigide, sans aucun contrôle de son calibre","Surtout musculaire, avec une fonction proprioceptive","Dépourvu de tout contrôle, simple passage pour l'œsophage","Situé à droite de la ligne médiane, en avant de l'aorte et de la veine cave"],"r":1,"e":"Il se trouve à gauche et sa fonction est d'éviter les régurgitations, ce que sa nature musculaire rend possible. Sa fonction est proprioceptive et quantitative.","s":0},{"q":"Au repos, la respiration implique :","o":["Le seul travail du diaphragme","Le diaphragme et les intercostaux","Tous les muscles accessoires","Les scalènes principalement"],"r":0,"e":"Le recrutement accessoire — sterno-cléido-occipito-mastoïdien, scalènes, pectoraux, rhomboïdes, grand dentelé — n'intervient qu'à l'effort ou en pathologie.","s":0},{"q":"La ligne de gravité passe par le foramen magnum avec une répartition du poids de la tête de :","o":["Moitié avant, moitié arrière","Deux tiers en avant, un tiers en arrière","Un tiers en avant, deux tiers en arrière","Totalement en avant"],"r":1,"e":"Elle passe également en avant de la cheville, ce qui crée un déséquilibre antérieur permanent que la musculature postérieure doit compenser.","s":0},{"q":"La vertèbre L3 se caractérise, dans l'organisation de la flexion, par le fait :","o":["Qu'elle est le sommet de la flexion lombaire, au-dessus du sacrum","Que la flexion s'organise autour d'elle, sans l'inclure","Qu'elle reste immobile pendant tout le mouvement","Qu'elle initie la flexion du tronc, avant L4 et L5"],"r":1,"e":"Elle constitue par ailleurs le centre de convergence de la chaîne croisée postérieure, le nombril étant celui de la chaîne croisée antérieure.","s":0},{"q":"Le centre de convergence de la chaîne croisée antérieure se situe :","o":["En L3","Au nombril","Au sternum","Au pubis"],"r":1,"e":"Cette organisation croisée rend compte des schémas de torsion du tronc, où l'épaule d'un côté se relie à la hanche opposée.","s":0},{"q":"L'orifice aortique est fibreux et non élastique afin :","o":["De renforcer la coupole diaphragmatique à chaque inspiration","De ne pas perturber le flux artériel","De permettre une régurgitation contrôlée","De faciliter la digestion par compression"],"r":1,"e":"L'aorte est en outre plaquée contre la colonne, près de la ligne de gravité, ce qui la maintient au centre lors des mouvements de torsion.","s":0},{"q":"L'œsophage adhère intimement à la colonne :","o":["Du processus basilaire de l'occipital jusqu'à T3","De C1 à C7, sur toute la colonne cervicale","De T3 à T12, sur toute la colonne thoracique","Uniquement au niveau du hiatus du diaphragme"],"r":0,"e":"Cette adhérence explique les relations entre posture cervicale haute et troubles fonctionnels digestifs, souvent négligées en pratique.","s":0},{"q":"L'équilibre postural désigne le maintien de la position du corps :","o":["Au repos","En mouvement","Dans les deux cas indifféremment","Uniquement debout"],"r":0,"e":"L'équilibre dynamique concerne le maintien de la stabilité en mouvement. Les deux relèvent du même processus général de stabilité posturale.","s":0},{"q":"Selon la loi de l'économie, le muscle qui travaille constamment et de façon économique est :","o":["Le transverse de l'abdomen","Le diaphragme","Le multifidus","Le grand dorsal"],"r":1,"e":"Toutes les fonctions physiologiques sont réalisées avec une dépense d'énergie contrôlée et régulée par ce muscle, actif en permanence.","s":0},{"q":"À l'inspiration, l'estomac :","o":["Se verticalise, tiré par le mésocôlon","Subit des pressions et s'horizontalise","Reste immobile, fixé par ses ligaments","Se vide dans le duodénum, par la pression du diaphragme qui descend"],"r":1,"e":"À l'expiration, le relâchement du mésocôlon le replace dans une position plus verticale : la respiration mobilise donc mécaniquement les viscères.","s":0},{"q":"Que signifie PNF ?","o":["Facilitation Neuromusculaire Proprioceptive","Programme Neuro-Fonctionnel","Physiothérapie Neuro-Fasciale","Protocole Neuromusculaire Fonctionnel"],"r":0,"e":"C'est un système de promotion de la réponse des mécanismes neuromusculaires par stimulation des propriocepteurs.","s":1},{"q":"Qui sont les fondateurs du PNF entre 1945 et 1951 ?","o":["Le Dr Herman Kabat et la kiné Margaret Knott","Dorothy Voss et Berta Bobath, en Angleterre","Philippe Souchard et Françoise Mézières, en France","Janet Carr et Roberta Shepherd, en Australie"],"r":0,"e":"En 1946, Voss et Knott écrivent le 1ᵉʳ livre sur le PNF.","s":1},{"q":"Comment définit-on la technique de PNF ?","o":["Des stimuli spécifiques pour obtenir des réponses, à partir du mouvement normal","Un protocole d'étirement passif global, chaîne par chaîne, sans contraction du patient","Une méthode de renforcement analytique, muscle par muscle, contre résistance","Une mobilisation articulaire passive, segment par segment"],"r":0,"e":"Le kinésithérapeute facilite, à partir d'un input proprioceptif, sur le SNP et le SNC, vers une réponse musculaire.","s":1},{"q":"Le PNF peut-il être utilisé seul ?","o":["Oui, comme méthode unique ou en association","Non, jamais seul","Uniquement en association avec la RPG","Uniquement en post-opératoire"],"r":0,"e":"C'est une méthode de facilitation utilisable seule ou en association.","s":1},{"q":"Quel est l'objectif principal du PNF ?","o":["Aider le patient à atteindre son plus haut niveau fonctionnel","Renforcer uniquement les muscles faibles, contre résistance","Étirer les chaînes musculaires rétractées, de façon globale","Diminuer la spasticité, par des postures inhibitrices prolongées et maintenues"],"r":0,"e":"Il peut aussi présenter différents objectifs secondaires, et présuppose toujours une évaluation.","s":1},{"q":"Sur quoi le PNF se base-t-il ?","o":["La neurophysiologie, le contrôle moteur et l'apprentissage moteur","La biomécanique articulaire seule, segment par segment, en chaîne ouverte","L'anatomie fonctionnelle uniquement, muscle par muscle, en position couchée","La physiologie cardio-respiratoire, à l'effort"],"r":0,"e":"Ces trois bases guident la planification de l'intervention.","s":1},{"q":"Quelle est la direction du développement du contrôle moteur ?","o":["Cervico-caudale et proximo-distale","Caudo-cervicale et disto-proximale","Uniquement proximo-distale","Aléatoire"],"r":0,"e":"Il s'exprime de façon ordonnée par des schémas de mouvement.","s":1},{"q":"Quelle est la première phase du contrôle moteur ?","o":["La mobilité, pour prendre une posture et initier le mouvement","La stabilité, pour tenir la nouvelle position sans aide","La stabilité dans la mobilité, pour aller de A vers B","Le skill, pour bouger dans toutes les directions"],"r":0,"e":"Puis stabilité, stabilité dans la mobilité, et skill.","s":1},{"q":"Que désigne la phase « stabilité dans la mobilité » ?","o":["Le mouvement contrôlé de A vers B","Le maintien d'une posture statique","Le mouvement dans toutes les directions","L'initiation du mouvement"],"r":0,"e":"La phase « skill » correspond aux segments qui se meuvent de façon contrôlée dans toutes les directions.","s":1},{"q":"Quelles sont les trois phases de l'apprentissage moteur ?","o":["Cognitive, associative, automatique","Mobilité, stabilité, skill","Préparation, action, correction","Initiation, exécution, correction"],"r":0,"e":"Elles se produisent à chaque phase du réapprentissage du contrôle moteur.","s":1},{"q":"Quel facteur conditionne principalement l'apprentissage moteur ?","o":["La répétition","La force développée","La vitesse d'exécution","L'amplitude articulaire"],"r":0,"e":"L'apprentissage moteur est un changement stable des comportements par acquisition de compétences via la pratique.","s":1},{"q":"Qu'est-ce que l'effet post-décharge ?","o":["L'effet d'un stimulus se poursuit après son arrêt","La combinaison de stimuli successifs, dans un temps court","La diffusion de la réponse vers d'autres muscles voisins","L'inhibition des antagonistes pendant la contraction"],"r":0,"e":"C'est l'un des six principes neurophysiologiques du PNF.","s":1},{"q":"Qu'est-ce que la sommation temporelle ?","o":["Des stimuli de basse fréquence successifs, qui s'additionnent dans le temps","Des stimuli simultanés, appliqués dans plusieurs zones différentes du corps","La propagation de la réponse vers des muscles voisins","L'excitation des antagonistes après celle des agonistes"],"r":0,"e":"La sommation spatiale concerne des stimuli simultanés dans différentes zones corporelles.","s":1},{"q":"Qu'est-ce que la sommation spatiale ?","o":["Des stimuli faibles appliqués en même temps dans plusieurs zones, qui se renforcent","Des stimuli successifs dans le temps, qui s'additionnent","L'effet persistant d'un stimulus après son interruption","L'inhibition réciproque des antagonistes pendant la contraction de l'agoniste"],"r":0,"e":"Elle cause une excitation par renforcement mutuel des stimuli.","s":1},{"q":"Que permet l'irradiation ?","o":["Activer des muscles faibles en stimulant des muscles préservés","Inhiber les antagonistes pendant la contraction des agonistes, par voie spinale","Prolonger l'effet d'un stimulus après son interruption","Synchroniser les mouvements des deux côtés du corps"],"r":0,"e":"Elle se caractérise par la diffusion et l'augmentation de la force de réponse. L'irradiation va du proximal vers le distal.","s":1},{"q":"Qu'est-ce que l'innervation réciproque ?","o":["L'excitation des agonistes s'accompagne de l'inhibition des antagonistes","L'excitation accrue des agonistes est suivie de l'excitation des antagonistes","La diffusion de la réponse aux groupes musculaires voisins","L'effet cumulatif des stimuli répétés dans le temps"],"r":0,"e":"L'induction sélective/successive correspond au contraire à l'excitation des antagonistes après celle des agonistes.","s":1},{"q":"Que produit une contraction musculaire résistée ?","o":["Plus de réponse du muscle, inhibition des antagonistes, stimulation proprioceptive","Uniquement une augmentation de la force maximale, sans autre effet sur le contrôle","Uniquement une fatigue musculaire, recherchée pour progresser","Une inhibition des agonistes, au profit des antagonistes"],"r":0,"e":"C'est la chaîne d'effets de la résistance décrite dans le cours. Les synergiques répondent aussi davantage.","s":1},{"q":"Quelles précautions accompagnent l'application de la résistance ?","o":["Un mouvement souple, sans douleur ni fatigue inutile, sans apnée","Une résistance toujours maximale, quel que soit l'objectif, le patient ou le type de contraction","Une résistance appliquée en apnée, pour stabiliser le tronc","Une résistance appliquée seulement en fin d'amplitude"],"r":0,"e":"Le choix entre résistance maximale et appropriée dépend de l'objectif, du patient et du type de contraction.","s":1},{"q":"Qu'est-ce que le renforcement en PNF ?","o":["Les muscles principaux potentialisent la force des accessoires agonistes","La propagation de l'influx nerveux vers les muscles voisins, par irradiation","L'augmentation progressive de la charge, séance après séance","L'ajout de séries supplémentaires en fin de séance"],"r":0,"e":"À distinguer de l'irradiation, qui est la propagation de la réponse d'influx nerveux.","s":1},{"q":"Que doit faire le contact manuel ?","o":["Indiquer la direction du mouvement et le faciliter par le toucher","Immobiliser le segment, pour éviter tout mouvement parasite du patient","Remplacer la commande verbale, quand le patient ne comprend pas la consigne","Empêcher tout mouvement, pour travailler en isométrique"],"r":0,"e":"Il applique des stimuli proprioceptifs sur peau, muscles, ligaments, tendons et points-clés.","s":1},{"q":"Comment le thérapeute doit-il se positionner ?","o":["Épaules et hanches dans la direction du mouvement, bras relâchés","Perpendiculaire au mouvement, bras tendus, coudes verrouillés","Toujours en fente latérale, quel que soit le schéma choisi","Les bras verrouillés en extension, le tronc immobile et droit, sans transfert de poids"],"r":0,"e":"La résistance est la conséquence de la position du corps du thérapeute.","s":1},{"q":"Quels sont les trois temps de la commande verbale ?","o":["Préparation, action, correction","Explication, démonstration, exécution","Initiation, maintien, arrêt","Consigne, silence, feedback"],"r":0,"e":"Les instructions doivent être claires, concises et le ton de voix adapté au contexte.","s":1},{"q":"Quel est l'effet de la traction en PNF ?","o":["Elle facilite et oriente le mouvement et étire les tissus","Elle favorise la stabilité, en rapprochant les surfaces articulaires de la région","Elle facilite la notion de charge, en comprimant l'articulation","Elle inhibe la contraction, en relâchant le muscle"],"r":0,"e":"L'approximation, à l'inverse, favorise la stabilité et facilite la notion de charge. Elle agit par stimulation des récepteurs articulaires.","s":1},{"q":"Quel est l'effet de l'approximation ?","o":["Elle favorise la stabilité, la notion de charge et la contraction","Elle allonge le tronc ou l'extrémité, en écartant les surfaces","Elle étire les tissus mous, en éloignant les insertions","Elle diminue le tonus, en relâchant le muscle sous tension, par inhibition réflexe"],"r":0,"e":"Elle rapproche les fibres musculaires et stimule les récepteurs articulaires.","s":1},{"q":"Comment doit être appliqué l'étirement en PNF ?","o":["Rapide, subtil et léger, au début du schéma, sur le muscle tendu","Lent et prolongé, en fin d'amplitude, sur le muscle relâché","En fin d'amplitude seulement, de façon brusque et forte","Sans résistance associée, pour ne pas fatiguer le muscle étiré à chaque répétition"],"r":0,"e":"Pour une plus grande efficacité, la contraction qui suit l'étirement doit être résistée.","s":1},{"q":"Combien de diagonales existe-t-il pour chaque partie du corps ?","o":["Deux","Une","Trois","Quatre"],"r":0,"e":"Pour chaque diagonale il existe deux schémas antagonistes : flexion et extension.","s":1},{"q":"Dans quels plans les schémas de PNF combinent-ils les mouvements ?","o":["Les trois plans, sagittal, frontal et transversal","Le seul plan sagittal, en flexion et extension","Les plans sagittal et frontal, sans rotation","Le seul plan transversal, en rotations"],"r":0,"e":"Sagittal : flexion/extension ; frontal : abduction/adduction ; transversal : rotation.","s":1},{"q":"Quelle articulation est libre au sein d'un schéma de facilitation ?","o":["L'articulation intermédiaire","L'articulation proximale","L'articulation distale","Aucune"],"r":0,"e":"Les articulations proximales et distales sont liées au sein du schéma.","s":1},{"q":"À quelles composantes est associée la rotation externe dans un schéma ?","o":["Supination, déviation radiale et inversion","Pronation, déviation cubitale et éversion","Flexion et adduction","Extension et abduction"],"r":0,"e":"La rotation interne est associée à pronation, déviation cubitale et éversion.","s":1},{"q":"Quelle est la différence entre traitement direct et indirect en PNF ?","o":["Le direct cible la zone lésée ; l'indirect, une zone moins lésée ou éloignée","Le direct est manuel ; l'indirect est verbal, sans aucun contact avec le patient","Le direct est passif ; l'indirect est actif, contre résistance","Aucune différence, les deux termes sont synonymes"],"r":0,"e":"Le traitement indirect met le focus sur la partie du corps la moins lésée.","s":1},{"q":"La phase « skill » du contrôle moteur correspond à :","o":["Assumer une posture et initier le mouvement","Rester stable dans la nouvelle position","Un mouvement contrôlé de A vers B","Des segments contrôlés dans toutes les directions"],"r":3,"e":"L'ordre complet : mobilité, stabilité, stabilité dans la mobilité, puis skill. Il faut évaluer où se situe le patient pour choisir la tâche et la position adéquates.","s":1},{"q":"Le développement du contrôle moteur suit une direction :","o":["Cervico-caudale et proximo-distale","Caudo-céphalique et disto-proximale","Disto-proximale, des mains vers le tronc","Aléatoire, selon l'enfant et son milieu"],"r":0,"e":"Postures et mouvements sont contrôlés par des commandes centrales et des réflexes spinaux, s'exprimant de façon ordonnée par des schémas de mouvement.","s":1},{"q":"La sommation spatiale se définit comme :","o":["Des stimuli successifs de basse fréquence, dans le temps","Des stimuli faibles et simultanés, dans plusieurs zones","Un effet qui persiste après l'arrêt du stimulus","Une réponse qui diffuse vers d'autres groupes"],"r":1,"e":"La sommation temporelle concerne la succession dans le temps, l'effet post-décharge la persistance après interruption, l'irradiation la diffusion. Ces stimuli se renforcent entre eux.","s":1},{"q":"L'irradiation permet, en pratique :","o":["D'activer des muscles faibles en stimulant des muscles préservés","D'inhiber les antagonistes pendant la contraction des agonistes","De prolonger l'effet d'un stimulus après son interruption complète","D'alterner agonistes et antagonistes, de façon rythmée et continue"],"r":0,"e":"C'est l'un des principes les plus exploités du PNF : recruter la force là où elle existe pour la faire diffuser là où elle manque. L'irradiation va du proximal vers le distal.","s":1},{"q":"L'induction sélective ou successive signifie que :","o":["L'excitation des agonistes s'accompagne de l'inhibition des antagonistes","L'excitation accrue des agonistes est suivie de celle des antagonistes","Les stimuli successifs s'additionnent dans le temps, jusqu'au seuil","La réponse persiste après l'arrêt du stimulus, quelques secondes"],"r":1,"e":"C'est l'innervation réciproque qui décrit l'excitation des agonistes accompagnée de l'inhibition des antagonistes — deux principes distincts à ne pas confondre.","s":1},{"q":"La contraction résistée en PNF produit :","o":["Une inhibition des synergiques et des agonistes, par fatigue","Plus de réponse musculaire, moins d'antagonistes, plus de proprioception","Une fatigue recherchée, signe d'efficacité de la séance de facilitation","Une diminution du contrôle moteur, par épuisement du muscle"],"r":1,"e":"Elle augmente aussi la réponse des synergiques. Elle doit permettre un mouvement souple et coordonné, sans douleur ni fatigue indésirable.","s":1},{"q":"Concernant la respiration pendant la résistance, le cours recommande :","o":["Une apnée d'effort, pour stabiliser le tronc","D'éviter les apnées, par une respiration contrôlée","Une hyperventilation, avant chaque contraction","De ne pas s'en préoccuper, le patient gère seul"],"r":1,"e":"L'apnée d'effort élève la pression intrathoracique et expose à des conséquences cardiovasculaires, sans bénéfice pour la facilitation recherchée.","s":1},{"q":"La position du kinésithérapeute en PNF suppose :","o":["Des bras tendus et verrouillés, pour transmettre la force du tronc","Épaules et hanches dans la direction du mouvement, bras relâchés","Une position fixe, quel que soit le schéma travaillé","Un appui sur la table, pour stabiliser le thérapeute"],"r":1,"e":"La résistance est décrite comme la conséquence de la position du corps du thérapeute, et non comme un effort des bras.","s":1},{"q":"La commande verbale en PNF se structure en trois temps :","o":["Préparation, action, correction","Inspiration, contraction, expiration","Départ, maintien, retour","Écoute, exécution, évaluation"],"r":0,"e":"Les instructions doivent être claires et concises, avec un ton adapté, et répétées pour stimuler l'engagement ou rediriger le mouvement.","s":1},{"q":"La traction en PNF produit ses effets par :","o":["Un rapprochement des surfaces articulaires, par compression","Un allongement du segment, avec stimulation articulaire","Une compression axiale, dans l'axe du membre et du tronc","Une vibration mécanique, appliquée sur le tendon"],"r":1,"e":"Elle facilite et oriente le mouvement et étire les tissus. L'approximation, à l'inverse, rapproche les fibres et favorise la stabilité.","s":1},{"q":"L'approximation facilite :","o":["Le mouvement, en écartant les surfaces","La stabilité, la charge et la contraction","L'étirement des tissus, en les allongeant","La relaxation, en relâchant le tonus musculaire"],"r":1,"e":"Elle agit également par stimulation des récepteurs articulaires, mais dans un sens opposé à celui de la traction.","s":1},{"q":"Pour une efficacité maximale, la contraction qui suit l'étirement doit être :","o":["Libre","Résistée","Lente","Excentrique"],"r":1,"e":"Le mouvement doit débuter à l'amplitude d'étirement du schéma ; l'étirement peut être rapide, subtil et léger sur le muscle sous tension.","s":1},{"q":"L'étirement en PNF facilite :","o":["Uniquement le muscle allongé, sans aucun effet à distance","Le muscle allongé, ceux de l'articulation et les synergiques","Les antagonistes, par inhibition réciproque spinale","Les muscles distaux uniquement, par irradiation du proximal"],"r":1,"e":"Cette diffusion de l'effet facilitateur rejoint le principe d'irradiation, qui structure toute la méthode.","s":1},{"q":"Dans un schéma de facilitation, l'articulation intermédiaire :","o":["Est fixée dans le schéma, sans mouvement possible","Est libre de fléchir, de s'étendre ou de rester fixe","Doit toujours être en flexion, quel que soit le schéma choisi","Est exclue du mouvement, maintenue par le kiné"],"r":1,"e":"Les articulations proximales et distales du membre sont, elles, liées au sein du schéma. Modifier l'action de l'intermédiaire est l'une des variations possibles.","s":1},{"q":"Dans les composantes d'un schéma, le croisement de la ligne médiane correspond à :","o":["L'abduction","L'adduction","La rotation externe","L'extension"],"r":1,"e":"L'éloignement de la ligne médiane correspond à l'abduction. La rotation externe s'associe à supination, déviation radiale et inversion.","s":1},{"q":"La rotation interne, dans les schémas PNF, s'associe à :","o":["Supination, déviation radiale et inversion","Pronation, déviation cubitale et éversion","Flexion et adduction","Extension et abduction"],"r":1,"e":"Ces correspondances permettent de construire un schéma cohérent sur toute la longueur du membre, du proximal au distal.","s":1},{"q":"Parmi les variations possibles d'un schéma, le cours cite :","o":["Modifier la position du patient et l'effet de la gravité","Changer de thérapeute à chaque séance, pour varier les stimuli","Augmenter le nombre de séances, de deux à cinq par semaine","Modifier la température de la pièce, pour le confort"],"r":0,"e":"S'y ajoutent la modification de l'articulation intermédiaire, de l'effet sur les biarticulaires, l'usage d'un input visuel différent et l'association à la fonction.","s":1},{"q":"Le traitement indirect en PNF consiste à :","o":["Travailler le muscle ou le membre lésé directement","Se centrer sur une zone moins lésée ou éloignée","Ne pas intervenir, en attendant la récupération spontanée","Utiliser uniquement la parole, sans aucun contact manuel"],"r":1,"e":"Il exploite l'irradiation : stimuler une région préservée peut faciliter une région atteinte, sans la solliciter directement.","s":1},{"q":"Parmi les composantes clés de la technique, le cours cite :","o":["L'usage de séquences du distal vers le proximal","Un mouvement strictement dans le plan sagittal","L'absence de résistance","Un travail sans commande verbale"],"r":0,"e":"S'y ajoutent les schémas en diagonale croisant la ligne médiane, le recours aux réflexes, le recrutement d'agonistes et d'antagonistes et les contractions répétées.","s":1},{"q":"Le cours résume l'exigence de l'exercice en PNF par la formule :","o":["Mouvement sans effort","Mouvement sans douleur, avec effort","Effort maximal, malgré la douleur","Mouvement passif seul"],"r":1,"e":"L'effort est nécessaire à la facilitation, mais la douleur signalerait une inadéquation de la résistance, de l'amplitude ou du positionnement.","s":1},{"q":"Qui a créé la méthode de Rééducation Posturale Globale et en quelle année ?","o":["Ph. Souchard en 1980/1981","Madame Mézières en 1947","Léopold Busquet en 1990","Tom Myers en 2001"],"r":0,"e":"La RPG est le fondement théorico-pratique de la rééducation posturale enseignée en EAIF III.","s":2},{"q":"Quel principe affirme que la cause peut être anatomiquement éloignée du symptôme ?","o":["La causalité","L'individualité","La globalité","La progressivité"],"r":0,"e":"Les trois principes fondamentaux sont individualité, causalité et globalité.","s":2},{"q":"Que signifie le principe de globalité ?","o":["Le corps humain doit être traité comme un tout","Chaque muscle doit être traité isolément","Tous les patients réagissent de la même façon","Le symptôme doit être traité en premier"],"r":0,"e":"Il faut identifier les implications des rétractions musculaires dans les pathologies musculo-squelettiques.","s":2},{"q":"Quelle est la logique de la démarche en RPG ?","o":["Partir du symptôme pour atteindre la cause","Partir de la cause pour expliquer le symptôme","Traiter la maladie et non l'individu","Traiter uniquement le segment douloureux"],"r":0,"e":"On intervient sur l'individu et non sur la maladie ; évaluation et raisonnement clinique sont déterminants.","s":2},{"q":"Quelle fonction musculaire la méthode valorise-t-elle ?","o":["La fonction statique","La fonction dynamique","La fonction pliométrique","La fonction aérobie"],"r":0,"e":"Les muscles de la statique sont sollicités en permanence, ce qui favorise leur raccourcissement.","s":2},{"q":"Quel est l'objectif de la RPG ?","o":["Identifier et étirer les muscles responsables des signes et symptômes","Renforcer les muscles faibles de façon concentrique, à charge élevée","Mobiliser les articulations bloquées par des techniques passives","Diminuer le tonus musculaire par le massage"],"r":0,"e":"Le raccourcissement des muscles statiques altère amplitude, qualité du mouvement et posture.","s":2},{"q":"Quel type de fibres prédomine dans les muscles de la statique ?","o":["Les fibres de type I","Les fibres de type II","Les fibres intermédiaires","Les fibres cardiaques"],"r":0,"e":"Ils sont très toniques, peu phasiques, avec des motoneurones alpha-toniques à décharge lente.","s":2},{"q":"Quelle caractéristique appartient aux muscles de la dynamique ?","o":["Vite fatigables, avec une énergie produite en anaérobie","Très résistants et peu fatigables, avec un métabolisme aérobie","Très fibreux, riches en collagène et en tissu conjonctif","Faits de fibres courtes, à contraction lente"],"r":0,"e":"Les muscles statiques sont au contraire peu fatigables, avec un métabolisme aérobie.","s":2},{"q":"Quels muscles sont plus aptes à résister à l'étirement ?","o":["Les muscles de la statique","Les muscles de la dynamique","Les deux également","Aucun"],"r":0,"e":"Les muscles dynamiques sont plus aptes à réaliser le mouvement.","s":2},{"q":"Quel groupe assure la fonction statique d'érection ?","o":["Triceps sural, ischio-jambiers, pelvi-trochantériens, droit fémoral, spinaux","Scalènes, trapèze supérieur, intercostaux et système musculo-fibreux médiastinal","Rotateurs internes et externes, adducteurs et abducteurs de hanche","Intercostaux et diaphragme, avec les muscles abdominaux"],"r":0,"e":"Ce sont les muscles antigravitaires.","s":2},{"q":"Quel groupe assure la fonction statique de suspension ?","o":["Scalènes, trapèze supérieur, intercostaux et système médiastinal","Triceps sural, ischio-jambiers, pelvi-trochantériens et spinaux","Adducteurs et abducteurs, rotateurs internes et externes de hanche","Spinaux et droit fémoral, antigravitaires"],"r":0,"e":"Ils assurent la suspension de la ceinture scapulaire et du thorax.","s":2},{"q":"Comment doivent être renforcés les muscles de la statique selon la RPG ?","o":["Par contractions isométriques en positions de plus en plus excentriques","Par contractions concentriques, à charge élevée et en course interne","En course interne maximale, muscle raccourci, contre résistance manuelle","Par électrostimulation, sans participation du patient"],"r":0,"e":"Ils ne doivent jamais être renforcés de façon concentrique ; on combine mouvement actif et étirement.","s":2},{"q":"Que devient un muscle statique raide et raccourci ?","o":["Il perd sa capacité à générer de la force","Il devient plus puissant, car plus raide et plus dense","Il gagne en endurance, par adaptation au raccourcissement","Il ne change pas sur le plan fonctionnel"],"r":0,"e":"Un muscle a plus de capacité à développer une contraction lorsqu'il est allongé.","s":2},{"q":"Quel est un exemple d'aponévrose d'intersection ?","o":["La ligne blanche abdominale","Le fascia lata","L'aponévrose plantaire","Le fascia thoraco-lombaire"],"r":0,"e":"Les aponévroses d'intersection correspondent au croisement de deux aponévroses.","s":2},{"q":"Quelle est la composition en collagène des tendons ?","o":["70 à 80 %","30 à 40 %","90 à 95 %","50 %"],"r":0,"e":"C'est ce qui les rend très résistants à l'étirement.","s":2},{"q":"Quel est le rôle des ligaments selon le cours ?","o":["Ils servent de freins articulaires","Ils assurent la coaptation articulaire","Ils permettent le glissement des muscles","Ils servent d'insertion aux muscles profonds"],"r":0,"e":"Les capsules articulaires maintiennent la coaptation et servent d'insertion à certains muscles.","s":2},{"q":"Quelle est la conséquence d'une traction sur une extrémité d'une chaîne musculaire ?","o":["Elle se transmet le long de la chaîne et se compense en un point quelconque","Elle reste locale, au niveau du muscle sur lequel on tire","Elle étire uniquement le muscle tracté, sans effet sur les autres muscles","Elle bloque l'articulation voisine, qui devient rigide"],"r":0,"e":"D'où la nécessité d'empêcher toutes les compensations pour obtenir l'étirement de la chaîne.","s":2},{"q":"Que comprend la chaîne maîtresse antérieure ?","o":["Le système de suspension cervico-thoraco-phrénique","Les spinaux et le triceps sural, en arrière","Le fascia plantaire et les fléchisseurs des orteils, sous le pied","Les rotateurs de hanche et les pelvi-trochantériens"],"r":0,"e":"Sa rétraction définit le type postural antérieur.","s":2},{"q":"Comment doivent travailler les antagonistes pour un mouvement normal ?","o":["En excentrique, pour contrôler le mouvement tout en s'allongeant","En concentrique uniquement, pour accélérer le mouvement","En isométrique uniquement, pour stabiliser l'articulation, sans aucun déplacement","Sans contraction, en se relâchant totalement"],"r":0,"e":"Il faut renforcer les agonistes, étirer les antagonistes, et aussi renforcer les antagonistes de façon excentrique.","s":2},{"q":"Quels muscles assurent essentiellement la position debout ?","o":["Les muscles de la statique, toniques","Les muscles de la dynamique, phasiques","Les deux à parts égales","Les muscles respiratoires"],"r":0,"e":"Il ne devrait pas être nécessaire que les phasiques se contractent pour maintenir la posture.","s":2},{"q":"Qu'est-ce qu'un « muscle vainqueur » ?","o":["Le plus raide, qui exerce le plus de pression et impose la déformation","Le plus fort en concentrique, qui gagne toujours contre son antagoniste","Le plus long, qui recouvre plusieurs articulations du membre","Le plus profond, qui stabilise les articulations"],"r":0,"e":"Le « muscle vaincu » est le moins raide, qui cède à la raideur du vainqueur.","s":2},{"q":"Par quoi commence une rééducation morphologique correcte ?","o":["Par l'étirement des muscles les plus raccourcis, qui causent la déformation","Par le renforcement des muscles vaincus, qui cèdent à la raideur des vainqueurs","Par la mobilisation articulaire passive des segments bloqués","Par le massage des muscles douloureux et contracturés"],"r":0,"e":"Il faut rééquilibrer les groupes musculaires de la même typologie : vainqueurs et vaincus.","s":2},{"q":"Qu'est-ce que le réflexe myotatique direct ?","o":["L'étirement rapide du fuseau provoque une contraction du muscle étiré","La contraction du muscle provoque son propre relâchement, par l'organe de Golgi","La contraction d'un agoniste inhibe son antagoniste, par la moelle","La traction constante déforme le muscle de façon permanente"],"r":0,"e":"Le réflexe myotatique inverse est celui où la contraction provoque un relâchement.","s":2},{"q":"Qu'est-ce que le fluage ?","o":["La déformation définitive d'un matériau sous une traction constante","La contraction réflexe d'un muscle en réponse à un étirement rapide","L'inhibition d'un antagoniste pendant la contraction de l'agoniste","La perte d'élasticité d'un tissu avec le vieillissement, après 60 ans"],"r":0,"e":"L'objectif est une réorganisation des chaînes macromoléculaires en position de plus grande longueur. La traction doit être prolongée.","s":2},{"q":"Quelle est la position initiale d'une posture RPG ?","o":["Celle que le patient tolère sans effort et sans douleur","La position d'étirement maximal de toute la chaîne musculaire","La position anatomique stricte, imposée dès le départ","La position antalgique spontanée du patient, quelle qu'elle soit"],"r":0,"e":"Elle peut être très éloignée de la position normale exigée par la posture, du fait d'une incapacité anatomique et fonctionnelle.","s":2},{"q":"Quel allongement produit la traction manuelle passive ?","o":["Un millimètre au-delà du point d'inextensibilité","Cinq centimètres au-delà du point d'inextensibilité","Le maximum tolérable par le patient, jusqu'à la douleur","Aucun allongement mesurable, seulement un relâchement"],"r":0,"e":"C'est une traction sûre et sans risques pour le patient.","s":2},{"q":"Pourquoi la décoaptation est-elle nécessaire ?","o":["La rétraction musculaire augmente la coaptation articulaire","Elle diminue seulement la douleur, sans effet mécanique","Elle accélère la séance en raccourcissant les postures","Elle évite le fluage des tissus, qui serait délétère"],"r":0,"e":"Elle doit être maintenue pendant toute la progression de la posture.","s":2},{"q":"Pourquoi la traction doit-elle être lente ?","o":["Pour éviter le réflexe myotatique direct","Pour économiser l'énergie du thérapeute","Pour raccourcir la durée de la séance","Pour augmenter la force de tension appliquée"],"r":0,"e":"Le temps de traction augmente l'allongement obtenu et permet de diminuer la force de tension.","s":2},{"q":"Quelle est la durée maximale d'application d'une posture ?","o":["30 minutes","10 minutes","60 minutes","5 minutes"],"r":0,"e":"Avec des intervalles de repos, mais les pauses ne doivent pas être prolongées car contre-productives.","s":2},{"q":"Sur quoi reposent les étirements obtenus par les postures ?","o":["Un travail actif du patient, avec traction et décoaptation par le kiné","Une traction passive exclusive, le patient restant totalement relâché","Un relâchement complet du patient, sans traction du kiné ni contraction","Une contraction concentrique maximale du patient, sans traction associée"],"r":0,"e":"Le rythme est important et une manualité brusque est interdite.","s":2},{"q":"Le principe d'individualité en RPG implique :","o":["D'appliquer le même protocole à tous les patients","De respecter l'individualité à tous les niveaux","De traiter uniquement le symptôme principal","De standardiser les postures pour comparer"],"r":1,"e":"Les trois principes fondamentaux sont individualité, causalité et globalité. Le cours résume la démarche : intervenir sur l'individu et non sur la maladie. Notamment au niveau anatomo-physiologique.","s":2},{"q":"La logique de la démarche en RPG consiste à :","o":["Partir de la cause pour atteindre le symptôme","Partir du symptôme pour atteindre la cause","Traiter uniquement la zone douloureuse","Traiter d'abord le muscle le plus faible"],"r":1,"e":"Le principe de causalité pose que la cause peut être anatomiquement éloignée du symptôme — d'où la nécessité d'un raisonnement clinique global.","s":2},{"q":"Les positions antalgiques adoptées spontanément par le patient :","o":["Résolvent le problème, à long terme","Altèrent la posture et retentissent sur la fonction","Restent sans conséquence, ni locale ni générale","Doivent être encouragées, car elles protègent"],"r":1,"e":"Elles évitent une douleur ou un blocage à court terme, mais installent des schémas qui aggravent le déséquilibre à plus long terme.","s":2},{"q":"Les muscles de la statique se caractérisent par des motoneurones alpha :","o":["Toniques, à décharge lente","Phasiques, à décharge rapide","Gamma uniquement","Sans particularité"],"r":0,"e":"Les muscles dynamiques ont au contraire des motoneurones alpha-phasiques à décharge rapide, adaptés aux contractions vigoureuses et brèves.","s":2},{"q":"Les muscles de la statique tirent leur énergie :","o":["De processus anaérobies","Du métabolisme aérobie","De la phosphocréatine","De la glycolyse rapide"],"r":1,"e":"Leurs contractions sont relativement lentes et ils sont peu fatigables — profil cohérent avec une sollicitation permanente.","s":2},{"q":"Les fibres musculaires des muscles statiques sont :","o":["Longues","Courtes","De longueur variable","Absentes"],"r":1,"e":"Les muscles dynamiques ont des fibres longues, adaptées au déplacement ; les statiques, riches en collagène, sont bâtis pour résister.","s":2},{"q":"La fonction statique de suspension est assurée notamment par :","o":["Le triceps sural, les ischio-jambiers et les spinaux","Scalènes, trapèze supérieur, intercostaux, médiastin","Les rotateurs internes et externes de hanche","Les adducteurs, les abducteurs et les pelvi-trochantériens"],"r":1,"e":"La fonction d'érection antigravitaire revient au triceps sural, aux ischio-jambiers, aux pelvi-trochantériens, au droit fémoral et aux spinaux.","s":2},{"q":"La fonction de maintien des segments dans l'axe correct est assurée par :","o":["Les spinaux et le droit fémoral","Les rotateurs et les adducteurs-abducteurs","Le diaphragme et les intercostaux","Les scalènes et le trapèze supérieur"],"r":1,"e":"Les muscles remplissant un rôle d'un degré de difficulté supérieur sont, selon le cours, plus volumineux, plus toniques et plus fibreux. Les rotateurs sont internes et externes.","s":2},{"q":"Un muscle statique constamment sollicité tend :","o":["À l'allongement, par le travail répété et permanent","Au raccourcissement et à la rigidité, faute de repos","À l'atrophie, par manque de sollicitation au quotidien","À l'hypertrophie, par excès de travail"],"r":1,"e":"Sa sollicitation est double : le tonus indispensable au maintien de la posture, et la contraction nécessaire aux mouvements.","s":2},{"q":"Selon la RPG, les muscles de la statique doivent être renforcés :","o":["De façon concentrique, à charge élevée","Par de l'isométrique, en positions de plus en plus excentriques","Par des mouvements rapides, répétés et contre une forte résistance","Sans résistance, en course interne maximale"],"r":1,"e":"La méthode combine mouvement actif et étirement : renforcer sans raccourcir davantage est tout l'enjeu.","s":2},{"q":"Le « muscle vainqueur », dans le raisonnement RPG, est :","o":["Le plus fort en force maximale","Le plus raide","Le plus volumineux","Le plus douloureux"],"r":1,"e":"Le muscle qui cède est le « muscle vaincu ». La règle pratique qui en découle : on commence toujours par étirer le plus raccourci.","s":2},{"q":"La durée maximale d'une posture en RPG est de :","o":["10 minutes","20 minutes","30 minutes","60 minutes"],"r":2,"e":"Au-delà, le bénéfice ne progresse plus et la tolérance du patient se dégrade, ce qui compromet la qualité de la posture elle-même.","s":2},{"q":"La lenteur de la traction en RPG a pour but :","o":["D'augmenter la douleur tolérée par le patient","D'éviter le déclenchement du réflexe myotatique direct","De gagner du temps sur la durée totale de la séance","De faciliter la contraction du muscle étiré"],"r":1,"e":"Un étirement rapide activerait les fibres Ia et provoquerait une contraction réflexe du muscle que l'on cherche précisément à allonger.","s":2},{"q":"La RPG agit principalement sur les muscles où prédominent :","o":["Les fibres de type I","Les fibres de type IIa","Les fibres de type IIb","Toutes les fibres également"],"r":0,"e":"Ce sont elles qui assurent le maintien du contrôle postural, et qui composent majoritairement les muscles de la statique.","s":2},{"q":"Les niveaux d'intervention de la RPG comprennent :","o":["La prévention, le traitement et l'entretien","Le diagnostic, le traitement et le suivi","La chirurgie, la rééducation et la réadaptation","L'urgence, l'aigu et le suivi à long terme"],"r":0,"e":"Ses domaines couvrent le musculo-squelettique, le neuromusculaire et le cardio-respiratoire, à tous les âges de la vie.","s":2},{"q":"Les auto-postures en RPG sont :","o":["Improvisées par le patient, selon ses sensations","Prescrites par le kiné, après évaluation et apprentissage","Réservées aux sportifs de haut niveau, entre les séances","Interdites en dehors du cabinet, faute de contrôle"],"r":1,"e":"Elles complètent les consultations individuelles où le kinésithérapeute intervient directement, et conditionnent la continuité du traitement.","s":2},{"q":"Le raccourcissement des muscles statiques entraîne, selon le cours :","o":["Une amélioration de la posture et de la qualité du mouvement","Moins d'amplitude, un mouvement altéré, une posture déformée, des symptômes","Un gain de force, par une meilleure longueur de travail des muscles","Aucune conséquence, ni sur la posture ni sur le mouvement"],"r":1,"e":"L'objectif de la méthode en découle directement : identifier et étirer les muscles responsables des signes et symptômes.","s":2},{"q":"Les muscles de la dynamique sont décrits comme :","o":["Très rouges, résistants et peu fatigables","Plus rosés, peu résistants et vite fatigables","Riches en collagène et très fibreux","À décharge lente et prolongée"],"r":1,"e":"Leurs contractions sont dynamiques, rapides et vigoureuses, avec une énergie fournie par des processus anaérobies.","s":2},{"q":"Le principe de globalité impose :","o":["Traiter le corps comme un tout et relier les rétractions aux pathologies","Traiter tous les patients de la même façon, avec les mêmes postures","Privilégier les exercices globaux, au détriment des postures","Allonger la durée des séances, pour couvrir tout le corps"],"r":0,"e":"Il complète les principes d'individualité et de causalité, et fonde le recours à des étirements impliquant simultanément toute une chaîne.","s":2},{"q":"La RPG a été créée par Philippe Souchard en :","o":["1970/1971","1980/1981","1990/1991","2000/2001"],"r":1,"e":"Le cours la présente comme le fondement théorico-pratique de la rééducation posturale enseignée dans le module.","s":2},{"q":"Combien de vertèbres compte la colonne vertébrale au total ?","o":["33","24","26","31"],"r":0,"e":"7 cervicales, 12 thoraciques, 5 lombaires, 5 sacrées et 4 coccygiennes.","s":3},{"q":"Combien de vertèbres thoraciques compte la colonne ?","o":["12","7","5","4"],"r":0,"e":"Elles s'articulent avec les côtes et ont un rôle de protection.","s":3},{"q":"Quel segment rachidien supporte les charges les plus importantes ?","o":["Le segment lombaire","Le segment cervical","Le segment coccygien","Le segment thoracique"],"r":0,"e":"C'est le siège privilégié des lombalgies professionnelles.","s":3},{"q":"Combien de vertèbres sacrées, et sous quelle forme ?","o":["5, soudées","4, mobiles","7, soudées","5, mobiles"],"r":0,"e":"Le sacrum transmet les forces vers le bassin ; le coccyx compte 4 vertèbres.","s":3},{"q":"Quel est le rôle des courbures physiologiques du rachis ?","o":["Amortir les contraintes","Limiter la mobilité","Protéger la moelle seule","Augmenter la taille"],"r":0,"e":"Leur perte ou leur exagération augmente la charge discale et postérieure.","s":3},{"q":"Qu'est-ce qui définit une posture contraignante ?","o":["Une position maintenue, extrême ou asymétrique, qui charge le corps","Toute position debout, quelle que soit sa durée de maintien","Toute position assise, quelle que soit la qualité du siège","Une position tenue moins d'une minute, même en amplitude extrême"],"r":0,"e":"La durée de maintien est aussi importante que l'amplitude.","s":3},{"q":"Quel est le principe fondamental de l'ergonomie ?","o":["Adapter le travail à l'être humain","Adapter l'humain au travail","Augmenter les cadences de production","Standardiser tous les postes"],"r":0,"e":"Elle concilie santé/sécurité et efficacité du système de production.","s":3},{"q":"Que désigne la « tâche » en ergonomie ?","o":["Ce qui est prescrit : l'objectif et les conditions imposées","Ce que fait réellement le travailleur : son activité concrète","La charge mentale : l'effort cognitif demandé au travailleur","Le résultat obtenu : la production réalisée"],"r":0,"e":"L'activité est ce qui est réellement fait pour atteindre l'objectif.","s":3},{"q":"Pourquoi l'écart tâche / activité est-il central en analyse ergonomique ?","o":["C'est dans cet écart que se logent les contraintes imprévues et les risques","Il mesure la productivité réelle de chaque travailleur, heure par heure","Il sert à fixer le salaire du travailleur, selon sa performance","Il n'a aucune importance pratique, seule la tâche prescrite compte vraiment"],"r":0,"e":"L'activité tient compte des capacités réelles, de l'état du matériel et des aléas.","s":3},{"q":"Quel domaine de l'ergonomie traite de la charge mentale et des interfaces homme-machine ?","o":["L'ergonomie cognitive","L'ergonomie physique","L'ergonomie organisationnelle","L'anthropométrie"],"r":0,"e":"L'ergonomie physique traite postures, manutention et aménagement du poste.","s":3},{"q":"De quoi relève l'ergonomie organisationnelle ?","o":["Structures, horaires, travail en équipe, communication","Postures, manutention et aménagement du poste","Mémoire de travail, prise de décision et charge mentale","Éclairage, bruit, température et vibrations au poste"],"r":0,"e":"Elle porte sur l'organisation du travail plus que sur le poste lui-même.","s":3},{"q":"Dans quelle catégorie classe-t-on le bruit et les vibrations ?","o":["Facteurs de risque physiques","Facteurs chimiques","Facteurs biologiques","Facteurs psychosociaux"],"r":0,"e":"Les facteurs physiques incluent aussi températures extrêmes, rayonnements et éclairage inadéquat.","s":3},{"q":"Quels facteurs de risque sont majeurs dans les professions de santé ?","o":["Les facteurs biologiques","Les vibrations","Les rayonnements ionisants uniquement","Les températures extrêmes"],"r":0,"e":"Bactéries, virus, champignons et parasites.","s":3},{"q":"Le manque d'autonomie et le harcèlement relèvent de quels facteurs ?","o":["Psychosociaux","Physiques","Chimiques","Liés à l'activité"],"r":0,"e":"On y ajoute la charge de travail excessive, le faible soutien social et l'insécurité de l'emploi.","s":3},{"q":"Les gestes répétitifs et la manutention manuelle relèvent de quels facteurs ?","o":["Facteurs liés à l'activité","Facteurs physiques","Facteurs psychosociaux","Facteurs chimiques"],"r":0,"e":"On y inclut aussi les postures contraignantes et la station debout ou assise prolongée.","s":3},{"q":"Pourquoi une intervention centrée uniquement sur le geste échoue-t-elle souvent dans les TMS ?","o":["Les TMS combinent répétitivité, force, posture et facteurs psychosociaux","Le geste n'a aucune influence sur l'apparition des TMS","Les TMS sont uniquement d'origine génétique","Seule la force compte, quelle que soit la répétition, la posture ou le stress"],"r":0,"e":"Le stress et une faible latitude décisionnelle majorent l'incidence des TMS.","s":3},{"q":"Qu'est-ce qu'une maladie professionnelle ?","o":["Une affection listée officiellement, au lien direct avec une exposition","Une affection multifactorielle, où le travail est un facteur parmi d'autres","Une affection préexistante, majorée par les conditions de travail","Toute maladie survenant pendant les heures de travail"],"r":0,"e":"Elle ouvre droit à réparation sans avoir à prouver individuellement le lien causal.","s":3},{"q":"Qu'est-ce qu'une maladie liée au travail ?","o":["Une affection multifactorielle, où le travail est un facteur parmi d'autres","Une affection reconnue et listée officiellement, ouvrant réparation","Une affection préexistante, sans lien avec l'activité professionnelle","Une maladie contagieuse contractée au travail"],"r":0,"e":"Il n'y a pas de reconnaissance automatique : l'enjeu est la prévention plutôt que la réparation.","s":3},{"q":"Qu'est-ce qu'une maladie aggravée par le travail ?","o":["Une affection préexistante, sans lien causal, mais majorée par le travail","Une maladie professionnelle reconnue et listée officiellement","Une maladie multifactorielle, dont le travail est un facteur parmi d'autres","Une maladie liée à l'âge uniquement"],"r":0,"e":"Elle justifie des aménagements de poste et un suivi adapté.","s":3},{"q":"Quel est l'ordre des cinq niveaux de prévention ?","o":["Primordiale, primaire, secondaire, tertiaire, quaternaire","Primaire, secondaire, tertiaire, quaternaire, primordiale","Primordiale, secondaire, primaire, tertiaire, quaternaire","Primaire, primordiale, tertiaire, secondaire, quaternaire"],"r":0,"e":"La prévention primordiale vise à empêcher l'apparition même du facteur de risque.","s":3},{"q":"Que vise la prévention primordiale ?","o":["Empêcher l'apparition même du facteur de risque dans l'environnement","Dépister précocement la maladie chez les travailleurs exposés","Limiter les séquelles de la maladie déjà installée","Éviter le surdiagnostic et le surtraitement, en protégeant de la médicalisation"],"r":0,"e":"Exemple : concevoir un poste qui n'introduit pas le risque, dès la conception.","s":3},{"q":"La substitution d'un produit dangereux relève de quel niveau de prévention ?","o":["Primaire","Primordiale","Secondaire","Tertiaire"],"r":0,"e":"La prévention primaire évite la survenue de la maladie chez des sujets sains exposés.","s":3},{"q":"Les examens périodiques et les audiométries relèvent de quel niveau ?","o":["Prévention secondaire","Prévention primaire","Prévention tertiaire","Prévention quaternaire"],"r":0,"e":"Il s'agit d'un dépistage précoce avant le stade symptomatique ou irréversible.","s":3},{"q":"Le reclassement professionnel et la reprise progressive relèvent de quel niveau ?","o":["Prévention tertiaire","Prévention secondaire","Prévention primaire","Prévention primordiale"],"r":0,"e":"La prévention tertiaire limite les séquelles et les incapacités d'une maladie installée.","s":3},{"q":"Que vise la prévention quaternaire ?","o":["Éviter le surdiagnostic, le surtraitement et la iatrogénie","Dépister précocement les maladies chez les exposés","Supprimer le risque à la source, dès la conception du poste","Réadapter le travailleur après la maladie"],"r":0,"e":"Elle protège de la médicalisation excessive et de la chronicisation par excès de soins.","s":3},{"q":"Quelle est la place de l'équipement de protection individuelle dans la hiérarchie des mesures ?","o":["Le dernier recours, après élimination, substitution, technique et organisation","La première mesure à mettre en place, avant toute autre action collective","Une mesure équivalente à la substitution du produit dangereux","Une mesure inutile, que l'on peut supprimer"],"r":0,"e":"On privilégie toujours l'élimination du risque et les protections collectives.","s":3},{"q":"Quel est l'objectif de l'examen d'embauche ?","o":["Vérifier l'aptitude, établir un état de référence, informer sur les risques","Dépister une maladie professionnelle déjà installée chez le travailleur","Réadapter le travailleur, après un arrêt prolongé","Évaluer la productivité, la motivation et la ponctualité du candidat"],"r":0,"e":"Il a lieu avant l'affectation à un poste à risque.","s":3},{"q":"Dans quel cas réalise-t-on un examen occasionnel ?","o":["Reprise après absence longue, plainte, changement de poste, grossesse","À intervalles réguliers fixés d'avance, quel que soit l'état du salarié","Uniquement avant l'embauche, pour vérifier l'aptitude","Uniquement au départ de l'entreprise, pour clôturer le dossier"],"r":0,"e":"Il permet de réévaluer l'aptitude et d'adapter le poste.","s":3},{"q":"À partir de quel effectif un service interne de prévention est-il requis ?","o":["400 travailleurs","50 travailleurs","100 travailleurs","1 000 travailleurs"],"r":0,"e":"En deçà, ou faute de compétences internes, l'entreprise fait appel à un service externe agréé.","s":3},{"q":"Quelle approche est recommandée dans les lombalgies liées au travail ?","o":["La reprise précoce et progressive de l'activité","Le repos strict prolongé jusqu'à disparition de la douleur","L'arrêt définitif du poste","L'immobilisation par corset systématique"],"r":0,"e":"L'objectif est de restaurer la fonction et la confiance dans le mouvement, tout en agissant sur les contraintes du poste.","s":3},{"q":"Le segment rachidien le plus mobile, très sollicité par le travail sur écran, est :","o":["Le cervical","Le thoracique","Le lombaire","Le sacré"],"r":0,"e":"Le segment thoracique, articulé avec les côtes, a une mobilité réduite et un rôle de protection ; le lombaire supporte les charges les plus importantes.","s":3},{"q":"Le segment coccygien, avec ses 4 vertèbres, est décrit comme :","o":["Le principal support de charge du rachis","Vestigial, point d'insertion musculo-ligamentaire","Le segment le plus mobile de toute la colonne","Absent chez l'adulte, car soudé au sacrum"],"r":1,"e":"Le segment sacré, formé de 5 vertèbres soudées, assure la transmission des forces vers le bassin. Le total est de 33 vertèbres.","s":3},{"q":"La perte ou l'exagération des courbures physiologiques sous l'effet de postures prolongées :","o":["Améliore l'amortissement des contraintes, à long terme","Charge davantage les disques et les structures postérieures","Reste sans conséquence sur le rachis et les disques","Renforce les muscles spinaux, par un travail permanent"],"r":1,"e":"Les courbures — lordose cervicale, cyphose thoracique, lordose lombaire — assurent l'amortissement des contraintes.","s":3},{"q":"Concernant la posture de travail, le cours souligne que :","o":["Seule l'amplitude compte, quelle que soit la durée de maintien","La durée compte autant que l'amplitude, une bonne posture tenue trop longtemps nuit","Une posture correcte n'est jamais nocive, quelle que soit sa durée de maintien","La durée de maintien n'a aucune importance pour le rachis"],"r":1,"e":"C'est un point capital pour le conseil en entreprise : il n'existe pas de bonne posture, seulement une bonne alternance de postures.","s":3},{"q":"L'ergonomie cognitive traite notamment :","o":["Des postures, de la manutention et des charges portées au poste","De la charge mentale, des décisions, de la mémoire, des interfaces","Des horaires, du travail en équipe et de la communication","De l'anthropométrie et des dimensions du poste de travail"],"r":1,"e":"L'ergonomie physique couvre postures, manutention et aménagement du poste ; l'organisationnelle les structures, horaires, communication et gestion de la qualité.","s":3},{"q":"Le bruit et les vibrations sont classés parmi les facteurs de risque :","o":["Physiques","Chimiques","Biologiques","Psychosociaux"],"r":0,"e":"S'y ajoutent les températures extrêmes, les rayonnements et un éclairage inadéquat.","s":3},{"q":"Le harcèlement et l'insécurité de l'emploi relèvent des facteurs de risque :","o":["Physiques","Chimiques","Psychosociaux","Liés à l'activité"],"r":2,"e":"Cette catégorie comprend aussi la charge de travail excessive, le manque d'autonomie, le faible soutien social et le conflit vie professionnelle-vie privée.","s":3},{"q":"Selon le cours, les troubles musculo-squelettiques résultent le plus souvent :","o":["D'un seul geste nocif, répété au poste","D'une combinaison de répétitivité, de force et de posture","D'une prédisposition génétique, quel que soit le poste","D'un traumatisme unique, au cours d'un accident"],"r":1,"e":"Les facteurs psychosociaux, comme le stress et une faible latitude décisionnelle, en majorent l'incidence — d'où l'échec des interventions centrées sur le seul geste.","s":3},{"q":"Une maladie professionnelle se distingue par le fait que :","o":["Elle est multifactorielle, le travail n'étant qu'un facteur parmi d'autres","Elle figure sur une liste officielle et ouvre réparation sans preuve individuelle","Elle préexistait à l'emploi et a été majorée par le travail","Elle n'ouvre aucun droit à réparation, même reconnue"],"r":1,"e":"La maladie liée au travail est multifactorielle et relève de la prévention plutôt que de la réparation ; la maladie aggravée par le travail préexistait.","s":3},{"q":"Une maladie aggravée par le travail justifie principalement :","o":["Une indemnisation automatique du salarié","Des aménagements de poste et un suivi adapté","Un licenciement pour inaptitude, sans reclassement","Aucune mesure particulière, faute de lien causal"],"r":1,"e":"Elle n'a pas de lien causal avec l'activité, mais les conditions de travail en majorent l'expression — ce qui appelle une adaptation, non une réparation.","s":3},{"q":"La prévention primordiale vise à :","o":["Dépister précocement la maladie chez les exposés","Empêcher l'apparition même du facteur de risque","Limiter les séquelles de la maladie installée","Éviter le surdiagnostic et le surtraitement des salariés"],"r":1,"e":"Elle passe par la conception ergonomique en amont : un poste conçu sans introduire le risque n'aura jamais besoin de protection.","s":3},{"q":"La prévention quaternaire a pour objet :","o":["La vaccination des travailleurs exposés, aux agents infectieux du poste","D'éviter le surdiagnostic, le surtraitement et la médicalisation excessive","Le reclassement professionnel, après une inaptitude au poste","Le dépistage précoce, des maladies liées au travail"],"r":1,"e":"Elle vise à éviter la iatrogénie et la chronicisation par excès de soins — enjeu majeur dans les lombalgies liées au travail.","s":3},{"q":"Dans la hiérarchie des mesures de prévention, l'équipement de protection individuelle est :","o":["La première réponse à privilégier","Le dernier recours","Équivalent aux mesures collectives","Sans utilité"],"r":1,"e":"L'ordre est : élimination du risque, substitution, mesures techniques et protections collectives, mesures organisationnelles, puis EPI.","s":3},{"q":"L'examen d'embauche a notamment pour objectif :","o":["De dépister une maladie déjà installée, chez le salarié","De vérifier l'aptitude, d'établir une référence et d'informer","De limiter les séquelles d'une maladie professionnelle, reconnue","D'évaluer le retour au travail, après un arrêt de longue durée"],"r":1,"e":"L'examen périodique relève de la prévention secondaire ; l'examen occasionnel réévalue l'aptitude lors d'un événement particulier.","s":3},{"q":"Un examen occasionnel est réalisé notamment :","o":["À intervalles réguliers, fixés d'avance par le médecin du travail","Lors d'une reprise, d'une plainte, d'un changement de poste, d'une grossesse","Avant l'affectation au poste à risque, comme lors de l'embauche","Systématiquement chaque année, pour tous les salariés de l'entreprise"],"r":1,"e":"Son objet est de réévaluer l'aptitude et d'adapter le poste en fonction de la situation nouvelle.","s":3},{"q":"L'analyse des risques est décrite comme une démarche :","o":["Ponctuelle et facultative","Obligatoire, continue et documentée","Réservée aux grandes entreprises","Purement médicale, sans les salariés"],"r":1,"e":"Elle enchaîne quatre temps : identifier les dangers, évaluer les risques, définir et hiérarchiser les mesures, évaluer leur efficacité.","s":3},{"q":"Parmi les interventions du kinésithérapeute en prévention primaire figurent :","o":["Gestes et postures, école du dos, aménagements, pauses actives","La thérapie manuelle des lombalgies chroniques, après l'arrêt","Le reconditionnement à l'effort, avant la reprise","L'éducation à la douleur, chez le salarié douloureux chronique"],"r":0,"e":"La thérapie manuelle et l'éducation à la douleur relèvent du traitement ; le reconditionnement à l'effort de la réinsertion.","s":3},{"q":"Dans l'axe réinsertion, le kinésithérapeute intervient notamment contre :","o":["La fatigue musculaire, en fin de journée","La kinésiophobie, ou peur du mouvement","L'absentéisme administratif, du salarié","Le bruit, au poste de travail"],"r":1,"e":"S'y ajoutent le reconditionnement à l'effort, la restauration fonctionnelle du rachis et l'accompagnement de la reprise progressive.","s":3},{"q":"Le message clé du cours sur les lombalgies liées au travail est que :","o":["Le repos prolongé donne les meilleurs résultats à long terme","Une reprise précoce et progressive fait mieux que le repos prolongé","Il faut attendre la disparition complète de la douleur avant de reprendre","L'arrêt de travail doit être le plus long possible pour guérir"],"r":1,"e":"L'objectif n'est pas d'attendre la fin de la douleur mais de restaurer la fonction et la confiance dans le mouvement, tout en agissant sur les contraintes du poste.","s":3},{"q":"L'évaluation ergonomique menée par le kinésithérapeute doit porter sur :","o":["La seule tâche prescrite, telle que décrite par l'organisation","Les contraintes réelles, donc l'activité et pas seulement la tâche","Les seuls antécédents médicaux du salarié, consignés au dossier","Les seules performances du poste, mesurées en volume produit"],"r":1,"e":"C'est dans l'écart entre le prescrit et le réel que se logent les contraintes non prévues, et donc les risques.","s":3},{"q":"Quelles sont les fausses articulations du complexe de l'épaule ?","o":["Sous-acromiale et scapulo-thoracique","Gléno-humérale et acromio-claviculaire","Sterno-costo-claviculaire et gléno-humérale","Acromio-claviculaire et scapulo-thoracique"],"r":0,"e":"Les vraies articulations sont la sterno-costo-claviculaire, l'acromio-claviculaire et la gléno-humérale.","s":4},{"q":"Quelle est l'amplitude d'élévation de la clavicule ?","o":["48°","15°","20°","50°"],"r":0,"e":"L'abaissement est de 15°, la protraction de 15-20°, la rétraction de 20-30°.","s":4},{"q":"Quelle rotation claviculaire est importante pour le rythme scapulo-huméral ?","o":["La rotation postérieure (50°)","La rotation antérieure (10°)","L'élévation","La protraction"],"r":0,"e":"La rotation postérieure atteint 50°, contre 10° pour la rotation antérieure.","s":4},{"q":"Qu'accompagne le mouvement d'élévation de la clavicule ?","o":["Un glissement inférieur de l'extrémité interne","Un glissement supérieur de l'extrémité interne","Un glissement antérieur de l'extrémité interne","Aucun glissement de l'extrémité interne, qui reste fixe"],"r":0,"e":"La protraction s'accompagne d'un glissement antérieur de l'extrémité interne.","s":4},{"q":"Quel muscle est le principal moteur de la protraction scapulaire ?","o":["Le dentelé antérieur","Le trapèze moyen","Les rhomboïdes","L'élévateur de la scapula"],"r":0,"e":"Sa faiblesse provoque une scapula alata ; le petit pectoral est accessoire.","s":4},{"q":"Quelle conséquence a la faiblesse du dentelé antérieur ?","o":["Une scapula alata","Une élévation permanente de l'épaule","Une rétraction scapulaire","Un abaissement de la clavicule"],"r":0,"e":"Le dentelé antérieur est essentiel à la protraction et à la rotation supérieure de la scapula.","s":4},{"q":"Quel mouvement scapulaire prévient le conflit sous-acromial ?","o":["La rotation supérieure","La rotation inférieure","La rétraction","L'abaissement"],"r":0,"e":"Elle est indispensable à l'abduction et à la flexion complètes de l'épaule.","s":4},{"q":"Quels muscles assurent la rotation supérieure de la scapula ?","o":["Les trapèzes supérieur et inférieur, le dentelé antérieur","Les rhomboïdes, l'élévateur de la scapula et le trapèze moyen","Le trapèze moyen seul, en contraction isométrique","Le petit pectoral seul, avec le subclavier"],"r":0,"e":"La rotation inférieure est assurée par les rhomboïdes, l'élévateur de la scapula et le trapèze moyen. Pour le dentelé antérieur, ce sont les fibres inférieures.","s":4},{"q":"Quel est le rôle de la rotation inférieure de la scapula ?","o":["Contrôler le retour en position neutre, surtout en excentrique","Élever le bras au-dessus de la tête, en flexion complète","Stabiliser la scapula pendant les mouvements de poussée","Prévenir la scapula alata, en plaquant le bord médial contre le gril"],"r":0,"e":"Elle accompagne la descente du bras.","s":4},{"q":"Quels os composent l'articulation sterno-costo-claviculaire ?","o":["L'extrémité médiale de la clavicule, le manubrium et le 1ᵉʳ cartilage costal","La clavicule et l'acromion, avec un disque intra-articulaire","La scapula et l'humérus, avec le labrum glénoïdien","La clavicule et la 2ᵉ côte, avec le sternum et le cartilage du 2ᵉ espace"],"r":0,"e":"Un disque intra-articulaire assure congruence et stabilité.","s":4},{"q":"Où prend origine la capsule de l'articulation gléno-humérale ?","o":["Autour du col anatomique de l'humérus","Sur le trochiter, à sa face supérieure","Sur le processus coracoïde, à sa base","Sur l'acromion, à sa face inférieure"],"r":0,"e":"Elle s'insère au niveau du labrum glénoïdien et du rebord de la cavité glénoïde.","s":4},{"q":"Quelle est la limite supérieure de l'articulation sous-acromiale ?","o":["Le ligament coraco-acromial","La tête de l'humérus","L'épine de la scapula","La clavicule"],"r":0,"e":"La limite inférieure est la tête de l'humérus.","s":4},{"q":"Quelle est la dimension de l'espace sous-acromial ?","o":["Environ 1 cm","Environ 3 cm","Environ 5 mm","Environ 2,5 mm"],"r":0,"e":"Sa limitation compromet la bourse sous-acromiale, la coiffe, la capsule et la longue portion du biceps.","s":4},{"q":"Quelle est la fonction principale de l'articulation sous-acromiale ?","o":["Protéger la tête humérale en haut et faciliter le glissement du sus-épineux","Produire la rotation externe de l'épaule, avec l'infra-épineux","Stabiliser l'épaule en avant, avec le ligament gléno-huméral","Transmettre les charges axiales du bras au tronc, par la clavicule et le sternum"],"r":0,"e":"Elle facilite le glissement entre le sus-épineux et le ligament coraco-acromial.","s":4},{"q":"Selon Bigliani et al. (1986), quel type d'acromion prédomine dans les ruptures complètes de coiffe ?","o":["Le type III (70 %)","Le type II (17 %)","Le type I (3 %)","Le type IV"],"r":0,"e":"Type III dans 70 %, type II dans 17 %, type I dans 3 %.","s":4},{"q":"Quel type d'acromion est le plus fréquent chez les patients souffrant de douleur d'épaule ?","o":["Le type II, courbe, dans 62 % des cas","Le type I, plat, dans 21 % des cas","Le type III, crochu, dans 17 % des cas","Le type IV, convexe, dans 5 % des cas"],"r":0,"e":"Sur 100 patients : type II 62 %, type I 21 %, type III 17 %.","s":4},{"q":"Où s'insère le ligament coraco-huméral ?","o":["Par deux faisceaux, sur le trochiter et le trochin","Sur le labrum uniquement, au pôle supérieur de la glène","Sur l'acromion, à sa face inférieure, par un seul faisceau large","Sur la clavicule, à son extrémité latérale"],"r":0,"e":"Il prend origine sur le bord externe du processus coracoïde.","s":4},{"q":"Où s'insère le ligament gléno-huméral supérieur ?","o":["Sur le trochiter","Sur le trochin","Sur l'acromion","Sur le processus coracoïde"],"r":0,"e":"Les gléno-huméraux moyen et inférieur s'insèrent sur le trochin.","s":4},{"q":"De combien le labrum augmente-t-il la profondeur glénoïdienne ?","o":["D'environ 2,5 mm à 5 mm","De 1 cm","De 10 mm à 20 mm","Il ne l'augmente pas"],"r":0,"e":"Cela favorise l'emboîtement huméral.","s":4},{"q":"Qu'est-ce que le « chock-block effect » du labrum ?","o":["Une butée mécanique face aux forces de translation humérale","Une compression négative intra-articulaire, par effet ventouse","Un renfort capsulaire antérieur et inférieur","Un mécanisme proprioceptif de protection"],"r":0,"e":"C'est le deuxième des quatre mécanismes de stabilisation du labrum.","s":4},{"q":"Quelle est la particularité de l'innervation du labrum ?","o":["Pas de mécanorécepteurs, seulement des terminaisons nerveuses libres","Une forte densité de mécanorécepteurs, surtout en antéro-inférieur","Une absence totale d'innervation, ni sensitive ni proprioceptive","Une innervation exclusivement sympathique, par le ganglion stellaire"],"r":0,"e":"Cela explique la faible douleur associée aux lésions labrales, malgré une instabilité significative.","s":4},{"q":"Quelle proportion de la longue portion du biceps est liée au labrum ?","o":["Environ 50 %","Environ 10 %","Environ 90 %","Aucune"],"r":0,"e":"C'est ce lien qui explique l'instabilité significative provoquée par les lésions labrales.","s":4},{"q":"Qu'est-ce qu'une lésion de Bankart ?","o":["Une désinsertion antéro-inférieure du labrum, typique des luxations","Une atteinte de l'origine du long biceps, au pôle supérieur du labrum","Une rupture du sus-épineux, près de son insertion sur le trochiter","Une fracture du trochiter, après une chute sur le moignon de l'épaule"],"r":0,"e":"La lésion SLAP correspond à l'atteinte de l'origine de la longue portion du biceps.","s":4},{"q":"Entre quels muscles passe l'artère subclavière avec le plexus brachial ?","o":["Entre le scalène antérieur et le scalène moyen","Entre le petit et le grand pectoral uniquement","Entre le trapèze et le rhomboïde","Entre le deltoïde et le supra-épineux"],"r":0,"e":"Elle passe ensuite sous la clavicule et entre les pectoraux jusqu'à l'aisselle, où elle devient artère axillaire.","s":4},{"q":"Quel nerf innerve l'articulation acromio-claviculaire ?","o":["Le nerf suprascapulaire et le nerf pectoral","Le nerf circonflexe seul, issu du tronc postérieur","Le nerf subclavier et le nerf thoracique long","Le nerf musculo-cutané et le nerf radial"],"r":0,"e":"La gléno-humérale est innervée par les nerfs pectoral, supra-scapulaire et circonflexe. Le nerf suprascapulaire est issu de C5-C6.","s":4},{"q":"Quel muscle initie l'abduction de 0° à 15° ?","o":["Le supra-épineux","Le deltoïde moyen","L'infra-épineux","Le subscapulaire"],"r":0,"e":"Le deltoïde moyen prend le relais de 15° à 90° ; le supra-épineux est aussi stabilisateur supérieur.","s":4},{"q":"Quel muscle est le stabilisateur antérieur de la tête humérale ?","o":["Le subscapulaire","L'infra-épineux","Le petit rond","Le triceps (longue portion)"],"r":0,"e":"L'infra-épineux et le petit rond sont stabilisateurs postérieurs.","s":4},{"q":"Selon Hik & Ackland (2019), quels muscles ont les plus grands bras de levier d'élévation humérale ?","o":["Les faisceaux antérieur et moyen du deltoïde","Le grand pectoral et le grand dorsal","Les muscles de la coiffe des rotateurs","Le triceps brachial et le biceps, aux deux chefs"],"r":0,"e":"Le grand pectoral, le grand dorsal et le grand rond agissent comme principaux abaisseurs.","s":4},{"q":"Quelles sont les trois composantes du stiffness musculaire ?","o":["Les propriétés intrinsèques, l'activation neuromusculaire, l'impact fonctionnel","La force, l'endurance et la souplesse du muscle étudié","La viscosité, l'élasticité et la plasticité, sans composante nerveuse active","Le tonus, la tension et la rigidité du muscle au repos"],"r":0,"e":"Le stiffness est la résistance viscoélastique et neuromusculaire à la déformation ou à l'allongement.","s":4},{"q":"Quelle est la différence entre feedforward et feedback ?","o":["Le feedforward planifie vite mais s'adapte peu ; le feedback corrige en temps réel","Le feedback précède le mouvement, le feedforward le corrige après coup","Le feedforward utilise l'information sensorielle en temps réel, pendant le geste","Les deux sont équivalents et interchangeables, quelle que soit la tâche"],"r":0,"e":"La copie efférente est envoyée au lobule pariétal supérieur et au cervelet pour comparer l'attendu et le réalisé. Le feedback est plus lent mais plus précis.","s":4},{"q":"L'amplitude de rétraction claviculaire est de :","o":["10°","15 à 20°","20 à 30°","48°"],"r":2,"e":"Repères claviculaires : élévation 48°, abaissement 15°, protraction 15 à 20°, rétraction 20 à 30°, rotation antérieure 10°, rotation postérieure 50°.","s":4},{"q":"L'élévation de la clavicule s'accompagne :","o":["D'un glissement supérieur de l'extrémité interne","D'un glissement inférieur de l'extrémité interne","D'un glissement antérieur de l'extrémité interne","D'aucun glissement de l'extrémité interne, qui reste fixe"],"r":1,"e":"C'est le principe du bras de levier autour de l'articulation sterno-costo-claviculaire : le déplacement latéral et le déplacement médial sont inversés.","s":4},{"q":"La protraction claviculaire s'accompagne :","o":["D'un glissement antérieur de l'extrémité interne","D'un glissement postérieur de l'extrémité interne","D'une rotation de l'extrémité interne","D'aucun mouvement associé de l'extrémité interne, qui reste fixe"],"r":1,"e":"Et inversement pour la rétraction. Ces couplages conditionnent les techniques de mobilisation de l'articulation sterno-costo-claviculaire.","s":4},{"q":"L'élévation scapulaire est assurée par :","o":["Le trapèze supérieur, l'élévateur et, en aide, les rhomboïdes","Le trapèze inférieur et le petit pectoral, avec le subclavier","Le dentelé antérieur, par ses fibres supérieures et moyennes","Le trapèze moyen, avec les rhomboïdes en auxiliaires"],"r":0,"e":"Elle maintient l'épaule élevée, soutient le poids en suspension et participe à la posture érigée.","s":4},{"q":"L'abaissement scapulaire fait intervenir :","o":["Le trapèze supérieur, avec l'élévateur de la scapula","Le trapèze inférieur, le petit pectoral, le bas du dentelé","Les rhomboïdes, avec le trapèze moyen","L'élévateur de la scapula, avec les rhomboïdes"],"r":1,"e":"Il stabilise la scapula lors des mouvements de poussée vers le bas, comme lors d'un transfert en appui sur les mains.","s":4},{"q":"La rétraction scapulaire est assurée par :","o":["Le dentelé antérieur et le petit pectoral","Le trapèze moyen et les rhomboïdes","Le trapèze inférieur","Le petit rond"],"r":1,"e":"Elle intervient dans les mouvements de tirage et joue un rôle important dans la posture et la stabilité scapulaire.","s":4},{"q":"La rotation inférieure de la scapula est assurée par :","o":["Le trapèze supérieur et inférieur avec le dentelé antérieur","Les rhomboïdes, l'élévateur de la scapula et le trapèze moyen","Le petit pectoral seul, avec le subclavier","Le grand dorsal, avec le grand rond et le grand pectoral"],"r":1,"e":"Elle contrôle le retour de la scapula en position neutre et joue un rôle important dans le contrôle excentrique.","s":4},{"q":"L'articulation sterno-costo-claviculaire comporte :","o":["Un ménisque latéral, en forme de croissant","Un disque intra-articulaire, source de congruence","Aucune structure intermédiaire entre les surfaces","Un labrum, comme celui de la cavité glénoïde"],"r":1,"e":"Elle unit l'extrémité médiale de la clavicule, la face supérieure du manubrium sternal et l'extrémité médiale du premier cartilage costal. Le disque apporte congruence et stabilité.","s":4},{"q":"La capsule gléno-humérale s'insère :","o":["Sur le col chirurgical de l'humérus, sous les tubercules","Sur le labrum glénoïdien et le rebord de la cavité glénoïde","Sur l'acromion, à sa face inférieure","Sur le processus coracoïde, à sa base"],"r":1,"e":"Elle prend origine autour du col anatomique de l'humérus. Les surfaces sont revêtues de cartilage hyalin : tête convexe contre glène concave.","s":4},{"q":"La limite inférieure de l'articulation sous-acromiale est :","o":["Le ligament coraco-acromial","La tête de l'humérus","L'acromion","Le tendon du supra-épineux"],"r":1,"e":"Sa limite supérieure est le ligament coraco-acromial. Sa fonction principale est la protection supérieure de la tête humérale.","s":4},{"q":"Dans l'étude de Bigliani et al. (1986) sur les ruptures complètes de coiffe, l'acromion de type III était retrouvé dans :","o":["3 % des cas","17 % des cas","70 % des cas","100 % des cas"],"r":2,"e":"Le type II l'était dans 17 % des cas et le type I dans 3 %, ce qui a établi le lien entre morphologie acromiale crochue et rupture de la coiffe.","s":4},{"q":"Chez 100 patients souffrant de douleur d'épaule, le type acromial le plus fréquent était :","o":["Le type I, plat, à 21 %","Le type II, courbe, à 62 %","Le type III, crochu, à 17 %","Le type IV, convexe"],"r":1,"e":"Sur 292 scapulas, la répartition était de 56,5 % de type II, 28,8 % de type III et 12,1 % de type I.","s":4},{"q":"Le type IV acromial, convexe, a été retrouvé sur 423 scapulas sèches dans :","o":["2,6 % des cas","12 % des cas","28 % des cas","56 % des cas"],"r":0,"e":"C'est la morphologie la plus rare, ce qui explique qu'elle soit peu documentée dans les séries cliniques.","s":4},{"q":"Chez les patients présentant des ruptures transfixiantes, le type III était retrouvé dans :","o":["13 % des cas, comme dans la population contrôle","39,6 % des cas, contre 13 % chez les contrôles","62 % des cas, contre 13 % dans la population contrôle","24,2 % des cas, contre 13 % chez les contrôles"],"r":2,"e":"Ce contraste avec la population contrôle est l'argument le plus fort en faveur d'un rôle causal de la morphologie acromiale.","s":4},{"q":"Le labrum augmente la profondeur glénoïdienne d'environ :","o":["1 mm à 2 mm","2,5 mm à 5 mm","5 mm à 10 mm","10 mm à 15 mm"],"r":1,"e":"Il double donc approximativement la profondeur de la cavité, ce qui contribue significativement à la stabilité d'une articulation très peu contrainte.","s":4},{"q":"Concernant l'innervation du labrum, le cours précise qu'il :","o":["Est riche en mécanorécepteurs, surtout en avant","N'a pas de mécanorécepteurs, seulement des terminaisons libres","Est totalement dépourvu d'innervation, sensitive comme proprioceptive","Contient des fuseaux neuromusculaires, comme les muscles"],"r":1,"e":"Cela limite son rôle proprioceptif direct, mais explique qu'une lésion labrale puisse être douloureuse.","s":4},{"q":"Le ligament coraco-huméral prend origine :","o":["Sur le bord externe du processus coracoïde","Sur l'acromion, à sa face inférieure et antérieure","Sur la glène, au pôle supérieur du labrum","Sur le col chirurgical de l'humérus"],"r":0,"e":"Il participe, avec la capsule et son renfort antéro-inférieur, à la stabilité passive de l'articulation gléno-humérale.","s":4},{"q":"Le contrôle en feedforward, appliqué à l'épaule, se caractérise par :","o":["Une correction pendant l'exécution, lente mais précise","Une anticipation, rapide mais moins adaptable","Une absence de contrôle","Un contrôle purement réflexe"],"r":1,"e":"Le feedback, à l'inverse, corrige pendant l'exécution : il est plus lent mais plus précis. Les deux modes se complètent.","s":4},{"q":"La rotation postérieure de la clavicule, d'une amplitude de 50°, est importante pour :","o":["La protraction scapulaire","Le rythme scapulo-huméral","L'abaissement de l'épaule","La stabilité sterno-claviculaire"],"r":1,"e":"Sans elle, la scapula ne peut accomplir sa rotation supérieure complète, et l'élévation du bras reste limitée.","s":4},{"q":"Les rôles du complexe de l'épaule énumérés par le cours comprennent :","o":["Chaîne cinétique, support opérationnel, équilibre stabilité-fonction","Uniquement la mobilité, au détriment de la stabilité","Uniquement la stabilité, au détriment de la mobilité, quel que soit le geste","La seule protection du plexus brachial et des vaisseaux"],"r":0,"e":"Cette tension entre stabilité et fonctionnalité est la caractéristique de l'épaule : l'articulation la plus mobile du corps est aussi la moins contrainte.","s":4},{"q":"Quelle est la fonction primaire du complexe lombo-pelvien ?","o":["Transférer les charges","Produire la force musculaire maximale","Protéger la moelle épinière","Permettre la rotation du tronc"],"r":0,"e":"La meilleure stratégie assure transfert de charge, contrôle de la rotation et translation, alignement optimal et équilibre.","s":5},{"q":"Que ne doit PAS faire une bonne stratégie de stabilisation ?","o":["Augmenter la pression intra-abdominale ou stresser les articulations","Maintenir le schéma respiratoire pendant l'effort","Contrôler la rotation et la translation du segment","Assurer l'alignement optimal, l'équilibre et le transfert de charge"],"r":0,"e":"Elle doit au contraire maintenir le schéma respiratoire (Lee, 2011).","s":5},{"q":"Comment définit-on la stabilité dynamique ?","o":["Résister au mouvement et le contrôler dans toute l'amplitude disponible","Rester immobile sous une charge, sans aucun mouvement, quelle que soit sa durée","Développer la force maximale des muscles du tronc, en isométrique","Disposer d'une amplitude articulaire complète, dans tous les plans"],"r":0,"e":"Elle dépend des sous-systèmes passif, actif, neural et émotionnel.","s":5},{"q":"Quel sous-système est constitué des tissus inertes ?","o":["Le sous-système passif","Le sous-système actif","Le sous-système neural","Le sous-système émotionnel"],"r":0,"e":"Il assure la stabilité articulaire passive.","s":5},{"q":"Quel est le rôle du sous-système émotionnel ?","o":["Le stress, l'anxiété et la peur gênent l'efficacité du contrôle moteur","Il produit la force musculaire du tronc, par la commande volontaire","Il assure la proprioception des articulations, par les récepteurs capsulaires","Il n'a aucun impact démontré sur la stabilité"],"r":0,"e":"L'état émotionnel est fondamental pour la santé et la récupération (Holstege).","s":5},{"q":"Que se passe-t-il quand la stabilité d'un sous-système diminue ?","o":["Un autre système compense, avec un mouvement anormal et excessif","Le mouvement s'arrête, le temps que le sous-système récupère sa stabilité","La douleur disparaît, car le système passif prend le relais","Le système passif se renforce, pour compenser le déficit"],"r":0,"e":"Tropp et al. (1993) : la compensation se fait sans contrôle musculaire adéquat.","s":5},{"q":"Que devient le multifidus quand la colonne lombaire reste longtemps en flexion ?","o":["Il se « turn off »","Il s'hypertrophie","Il devient hyperactif","Il n'est pas affecté"],"r":0,"e":"Richardson et al. (2004) ; Williams et al. (2000) montrent des altérations du schéma d'activation.","s":5},{"q":"Qu'est-ce que la zone neutre ?","o":["Une zone proche de la position neutre, où la résistance passive est minimale","La zone de fin d'amplitude, où le système passif limite le mouvement","L'amplitude totale de mouvement disponible, d'une butée à l'autre","La zone où la douleur apparaît pendant le mouvement"],"r":0,"e":"La zone élastique va de la fin de la zone neutre à la fin de l'amplitude physiologique (Panjabi, 1992).","s":5},{"q":"Qu'est-ce que la pars interarticularis ?","o":["La partie entre les processus articulaires supérieur et inférieur","Le disque intervertébral, entre deux corps vertébraux voisins","Le ligament jaune, tendu entre deux lames vertébrales voisines","L'apophyse épineuse, à l'arrière de l'arc"],"r":0,"e":"Elle contribue à la stabilité de la colonne vertébrale.","s":5},{"q":"Qui a proposé la classification des muscles en systèmes local et global ?","o":["Bergmark (1989)","Panjabi (1992)","Comerford & Mottram (2001)","Lee (2004)"],"r":0,"e":"Local = stabilité segmentaire ou intra-pelvienne ; global = stabilité régionale.","s":5},{"q":"Quelle est la caractéristique des stabilisateurs locaux ?","o":["Mono-articulaires et profonds","Poly-articulaires et superficiels","Mono-articulaires et superficiels","Poly-articulaires et profonds"],"r":0,"e":"Les stabilisateurs globaux sont mono-articulaires superficiels, les mobilisateurs globaux poly-articulaires.","s":5},{"q":"Quel type de contraction caractérise les stabilisateurs locaux ?","o":["Tonique isométrique, constante, quelle que soit la direction","Tonique excentrique, dépendante de la direction du mouvement","Phasique concentrique, brève et puissante","Balistique, rapide, sans contrôle de la direction"],"r":0,"e":"Les stabilisateurs globaux ont une contraction tonique excentrique, les mobilisateurs une contraction phasique concentrique.","s":5},{"q":"Quel muscle appartient aux stabilisateurs locaux ?","o":["Le transverse de l'abdomen","Le droit de l'abdomen","Le grand dorsal","Les ischio-jambiers"],"r":0,"e":"Système local : transverse de l'abdomen, multifidus, diaphragme, plancher pelvien, psoas (fibres postérieures).","s":5},{"q":"Quel muscle est un mobilisateur global ?","o":["Le grand dorsal","Le multifidus","Le moyen fessier","Le transverse de l'abdomen"],"r":0,"e":"Mobilisateurs globaux : droit de l'abdomen, grand dorsal, ischio-jambiers, piriforme.","s":5},{"q":"Comment se définit le core ?","o":["La zone comprise entre le diaphragme et le plancher pelvien","La seule région lombaire, de L1 à L5, sans le bassin","Les abdominaux superficiels, droit et obliques externes","Le bassin osseux, avec les deux os coxaux et le sacrum"],"r":0,"e":"Il inclut la zone inférieure de la colonne dorsale, la colonne lombaire et la zone du bassin.","s":5},{"q":"Quand les muscles du système local doivent-ils stabiliser les articulations ?","o":["Avant qu'elles soient soumises à des charges additionnelles","Pendant la charge uniquement, au moment de l'effort maximal","Après la charge, pour récupérer la position neutre","Uniquement au repos, en position allongée"],"r":0,"e":"C'est la définition de la stabilité du core selon Leetun et al. (2004).","s":5},{"q":"Qu'est-ce que la form closure ?","o":["La forme et l'orientation articulaires qui favorisent la stabilité","Les forces compressives apportées par les muscles et les fascias autour de l'articulation","La pression intra-abdominale générée par le diaphragme","La rigidité articulaire obtenue par co-contraction"],"r":0,"e":"La force closure correspond aux forces compressives apportées par ligaments, muscles et fascias.","s":5},{"q":"Qu'apporte la force closure ?","o":["Un auto-verrouillage articulaire, qui augmente la rigidité segmentaire","La forme des surfaces articulaires, qui s'emboîtent d'elles-mêmes","La mobilité maximale du segment, dans toute l'amplitude","La souplesse ligamentaire, qui absorbe les chocs"],"r":0,"e":"Elle augmente le contrôle segmentaire, améliore la distribution de charge et diminue le stress des structures passives.","s":5},{"q":"Quels sont les trois mécanismes de la stabilité du core ?","o":["Pression intra-abdominale, tension du fascia thoraco-lombaire, rigidité articulaire","Force, endurance et souplesse des muscles du tronc","Mobilité, stabilité et coordination des segments vertébraux, de façon dissociée","Feedback, feedforward et proprioception du rachis"],"r":0,"e":"Ce sont les trois mécanismes décrits dans le cours.","s":5},{"q":"Quels muscles génèrent la pression intra-abdominale ?","o":["Le diaphragme, le plancher pelvien et le transverse de l'abdomen","Le droit de l'abdomen et les obliques internes et externes","Le grand dorsal, le carré des lombes et les érecteurs du rachis","Les ischio-jambiers et les fessiers"],"r":0,"e":"Leur contraction coordonnée augmente directement la rigidité physiologique vertébrale (Hodges et al., 1999).","s":5},{"q":"Quels mécanorécepteurs contient le fascia thoraco-lombaire ?","o":["Les corpuscules de Ruffini et de Pacini","Les fuseaux neuromusculaires et les fibres Ia","Les organes tendineux de Golgi, à la jonction","Les corpuscules de Meissner et de Merkel"],"r":0,"e":"Il s'étend du bassin jusqu'au crâne et couvre les muscles profonds de la colonne (Norris, 2008).","s":5},{"q":"Que se passe-t-il si le transverse de l'abdomen développe une tension d'un seul côté ?","o":["Un déplacement peut survenir","Le mouvement est limité","La stabilité augmente","Rien ne change"],"r":0,"e":"Si la tension est égale des deux côtés, le mouvement sera limité (Richardson et al., 2004).","s":5},{"q":"Quand le diaphragme s'active-t-il lors d'une flexion rapide de l'épaule ?","o":["En même temps que le transverse, environ 20 ms avant le deltoïde","Après le deltoïde, environ 20 ms après le début du mouvement","20 s avant le mouvement, en préparation consciente","Il ne s'active pas, la flexion de l'épaule ne sollicitant pas le tronc"],"r":0,"e":"C'est un ajustement postural anticipatoire décrit par Hodges. C'est l'activité EMG du deltoïde qui sert de repère.","s":5},{"q":"Comment le plancher pelvien répond-il à une contraction abdominale forte ?","o":["Toute sa musculature se contracte","Il se relâche","Il ne réagit pas","Il se contracte seulement d'un côté"],"r":0,"e":"Lors d'un recrutement abdominal sélectif et doux, il répond par une réaction spécifique (Sapsford et al., 2001).","s":5},{"q":"Comment définit-on l'instabilité vertébrale ?","o":["L'incapacité à maintenir un déplacement sous charge sans troubles neurologiques","Une hypermobilité articulaire isolée, sans aucun symptôme ni déformation","Une faiblesse musculaire du tronc, mesurée au testing des abdominaux et des spinaux","Une perte d'amplitude du rachis, mesurée à l'inclinomètre"],"r":0,"e":"Définition de White, Panjabi et al. (1990). Sans douleur ni déformation non plus.","s":5},{"q":"Quel signe caractérise les mouvements répétés sans contrôle ?","o":["Une perte bilatérale de la contraction anticipatoire du multifidus","Une hyperactivité du transverse, en continu","Un raccourcissement du psoas, du côté douloureux et du côté sain","Une augmentation de la rigidité segmentaire"],"r":0,"e":"On note aussi un retard du grand fessier et une activation anticipée des ischio-jambiers du côté symptomatique.","s":5},{"q":"Comment les stabilisateurs locaux réagissent-ils à la douleur ?","o":["Par l'inhibition","Par des spasmes","Par une hyperactivité","Par un raccourcissement"],"r":0,"e":"Les mobilisateurs globaux réagissent par des spasmes ; les globaux par un recrutement tonique insuffisant.","s":5},{"q":"La récupération de la dysfonction est-elle spontanée après disparition de la douleur ?","o":["Non, la douleur peut disparaître et la dysfonction persister","Oui, systématiquement, dès que la douleur a disparu","Oui, si la douleur a duré moins de six semaines au total","Seulement chez les sportifs, grâce à l'entraînement"],"r":0,"e":"Ces dysfonctions sont réversibles par l'application de stimuli adéquats à leur fonction (Hides et al., 1996).","s":5},{"q":"Quelle posture se caractérise par des abdominaux déconnectés et une compensation en extension ?","o":["La posture cypho-lordotique","Le sway back, ou dos creux relâché","Le dos plat, sans courbures","La posture neutre, alignée"],"r":0,"e":"Le sway back donne une compensation en flexion avec obliques, multifidus et fessiers déconnectés.","s":5},{"q":"Quel sling est composé du grand dorsal, du fascia thoraco-lombaire et du grand fessier controlatéral ?","o":["Le sling oblique postérieur","Le sling longitudinal profond","Le sling oblique antérieur","Le sling latéral"],"r":0,"e":"Il favorise l'efficience de l'extension, le contrôle lombo-pelvien et le contrôle des rotations.","s":5},{"q":"Selon Lee (2011), la meilleure stratégie de stabilisation assure :","o":["Un transfert de charge, le contrôle des rotations et translations","La seule rigidité du tronc, par contraction maximale des abdominaux","Une contraction maximale et permanente des muscles profonds","L'immobilisation du rachis pendant tout mouvement des membres"],"r":0,"e":"La stratégie ne doit créer de stress dans aucune articulation, ni augmenter la pression intra-abdominale de façon inadaptée, et doit maintenir le schéma respiratoire. Elle assure aussi un alignement optimal et l'équilibre.","s":5},{"q":"Parmi les éléments que la stratégie de stabilisation doit maintenir (Lee, 2004), le cours cite :","o":["L'interprétation juste des afférences, avec une réponse motrice adaptée","La force maximale des abdominaux, en contraction isométrique","Une apnée contrôlée, pour verrouiller le tronc pendant l'effort","Une immobilité complète du rachis, quelle que soit la tâche demandée"],"r":0,"e":"S'y ajoutent l'intégrité des structures, la capacité de contraction prolongée et coordonnée, la compression articulaire adéquate et le contrôle neural.","s":5},{"q":"Selon Saal et Saal (1989), sont fondamentaux en stabilisation :","o":["La force maximale des abdominaux superficiels, en flexion du tronc","La vitesse de réaction des abdominaux, la dissociation des profonds","L'endurance des seuls spinaux, en extension prolongée","L'amplitude lombaire, mesurée en flexion et en extension"],"r":1,"e":"Le délai de réaction compte davantage que la force brute : un muscle puissant qui se contracte trop tard ne protège pas l'articulation.","s":5},{"q":"La stabilité dynamique se définit comme :","o":["L'immobilité du rachis sous une charge prolongée","La capacité à résister au mouvement et à le contrôler","La force maximale développée par les muscles du tronc","La rigidité passive des ligaments et des capsules vertébrales"],"r":1,"e":"Elle repose sur quatre sous-systèmes selon Panjabi : passif, actif, neural et émotionnel. Ce contrôle porte sur toute l'amplitude disponible.","s":5},{"q":"Le sous-système neural, dans le modèle de Panjabi, comprend :","o":["Les tissus inertes : os, ligaments, capsules, disques","Les tissus contractiles : muscles, tendons","Le système nerveux : nerfs, propriocepteurs, centres","Les émotions : stress, anxiété, peur du mouvement"],"r":2,"e":"Il assure le feedback de surveillance de l'information et la modulation de la réponse — c'est le chef d'orchestre du système.","s":5},{"q":"Le sous-système émotionnel, selon Holstege, influence la stabilité parce que :","o":["Le stress, l'anxiété et la peur gênent l'efficacité du contrôle moteur","Il modifie la structure osseuse du rachis, à long terme","Il augmente la force musculaire du tronc, en cas de stress","Il n'a qu'un rôle marginal, sans effet mesurable sur le mouvement"],"r":0,"e":"Le cours précise que l'état émotionnel est fondamental pour la santé et la récupération : ce n'est pas un facteur annexe mais un sous-système à part entière.","s":5},{"q":"Selon Tropp et ses collaborateurs (1993), lorsque la stabilité d'un sous-système diminue :","o":["Le mouvement s'arrête, le temps que la stabilité revienne","Un autre système compense, avec un mouvement anormal et mal contrôlé","La douleur disparaît, grâce au relais d'un autre système","La stabilité globale augmente, par l'effet de la compensation musculaire"],"r":1,"e":"La compensation masque le déficit initial tout en produisant des contraintes nouvelles : c'est le mécanisme de nombreuses récidives.","s":5},{"q":"O'Sullivan (2002) a montré que les stabilisateurs lombo-pelviens sont :","o":["Plus actifs en postures passives, assis affaissé ou debout relâché","Actifs en posture érigée bien alignée, moins actifs en slump ou en sway","Toujours également actifs, quelle que soit la posture adoptée","Inactifs en position debout, quel que soit l'alignement du rachis"],"r":1,"e":"C'est un argument direct en faveur de l'éducation posturale : la posture affaissée désactive précisément les muscles qui protègent le rachis.","s":5},{"q":"Richardson et ses collaborateurs (2004) ont montré que le multifidus :","o":["S'hypertrophie quand la flexion lombaire se prolonge","Se « désactive » si le rachis reste longtemps fléchi","Ne dépend pas de la position du rachis lombaire","Ne participe pas du tout à la stabilité lombaire"],"r":1,"e":"Williams et ses collaborateurs (2000) avaient montré que le maintien en flexion altère le schéma d'activation de ce muscle.","s":5},{"q":"La zone neutre se définit comme :","o":["Toute l'amplitude physiologique, d'une butée à l'autre","Une petite zone proche du neutre, à résistance passive minimale","La fin d'amplitude, où les ligaments se tendent et freinent","La zone de blocage, où le mouvement devient impossible"],"r":1,"e":"La zone élastique s'étend de la fin de la zone neutre à la fin de l'amplitude physiologique, où le système passif limite et contrôle (Panjabi, 1992).","s":5},{"q":"La pars interarticularis est la partie de la vertèbre située :","o":["Entre les processus articulaires supérieur et inférieur","Entre le corps vertébral et l'arc postérieur, au pédicule","Au sommet du processus épineux, à l'arrière de l'arc","Dans le foramen intervertébral, autour de la racine nerveuse"],"r":0,"e":"Elle contribue à la stabilité de la colonne, et sa fracture de fatigue constitue la spondylolyse, fréquente chez le sportif jeune.","s":5},{"q":"Les ajustements posturaux anticipatoires supposent que les stabilisateurs :","o":["Réagissent après le mouvement, pour corriger","Se contractent pour préparer le système à la force imminente","Restent passifs jusqu'à la fin du geste","Se relâchent avant l'effort, pour laisser bouger le tronc"],"r":1,"e":"Leur retard ou leur absence est l'une des anomalies les mieux documentées dans la lombalgie chronique.","s":5},{"q":"La douleur, dans le contrôle de la stabilité lombaire :","o":["Améliore la contraction musculaire, par une vigilance accrue","Peut inhiber la contraction et fausser l'alignement","Est sans effet moteur, seulement sensitif et émotionnel","Renforce l'alignement, par une protection active du segment"],"r":1,"e":"Les postures antalgiques renforcent alors le mauvais alignement, ce qui crée un cercle d'entretien entre douleur et dysfonction. L'alignement est faussé par les postures antalgiques.","s":5},{"q":"Bergmark (1989) distingue le système local, essentiel à :","o":["La stabilité segmentaire ou intra-pelvienne","La stabilité régionale","Le contrôle de l'orientation du thorax","Le mouvement des membres"],"r":0,"e":"Le système global assure la stabilité régionale et contrôle l'orientation du thorax par rapport au bassin, ou des membres par rapport au tronc.","s":5},{"q":"Le form closure désigne :","o":["Les forces compressives apportées par les muscles et les fascias","La forme, la structure et l'orientation articulaire","La pression intra-abdominale du caisson abdominal","La tension du fascia thoraco-lombaire, sous l'effet du grand dorsal"],"r":1,"e":"Le force closure correspond aux forces compressives actives. La stabilité résulte de la combinaison des deux.","s":5},{"q":"La stabilité du core résulte, selon le cours, de :","o":["La pression abdominale, la tension du fascia, la rigidité articulaire","La seule contraction du transverse de l'abdomen, en isométrique","La seule force des spinaux, en extension contre résistance","La rigidité passive des ligaments, sans participation musculaire"],"r":0,"e":"Ces trois mécanismes agissent simultanément : aucun ne suffit isolément à assurer le transfert de charge. Le fascia en jeu est le fascia thoraco-lombaire.","s":5},{"q":"La fonction primaire du complexe lombo-pelvien est :","o":["De produire le mouvement","De transférer les charges","De protéger la moelle","De permettre la respiration"],"r":1,"e":"Tout le reste en découle : contrôle du mouvement, alignement, équilibre et protection des organes s'ordonnent autour de cette fonction.","s":5},{"q":"Parmi les objectifs de la stabilisation lombo-pelvienne, le cours cite :","o":["Contrôler le mouvement, éviter les lésions, protéger les organes","Maximiser la force des muscles du tronc, en charge maximale","Limiter toute mobilité du rachis, pour le protéger des charges","Augmenter l'amplitude du rachis dans tous les plans de l'espace"],"r":0,"e":"La sécurité du mouvement, et non son amplitude ou sa puissance, est le critère retenu pour juger d'une bonne stratégie.","s":5},{"q":"Le sous-système passif correspond :","o":["Aux tissus contractiles : muscles et tendons du tronc","Aux tissus inertes : stabilité articulaire passive","Au système nerveux : nerfs et centres de contrôle","À l'état émotionnel : stress, anxiété et peur"],"r":1,"e":"Il limite et contrôle la fin de l'amplitude disponible, dans la zone élastique, mais offre peu de résistance dans la zone neutre.","s":5},{"q":"La stratégie de stabilisation, selon le cours, ne doit pas :","o":["Maintenir le schéma respiratoire pendant tout l'effort","Stresser les articulations ou monter trop la pression abdominale","Contrôler le mouvement dans toute l'amplitude disponible","Assurer l'alignement optimal et le transfert de charge entre segments"],"r":1,"e":"Une stratégie qui rigidifie en bloquant la respiration protège peut-être le segment visé, mais au prix de contraintes reportées ailleurs.","s":5}]};
